# Mobile lists: reuse the existing filtered data, with bounded rendering cost.
finance_list_ui <- function(ns, id, table_ui, search = TRUE) {
  shiny::div(class = "fm-list",
    if (search) shiny::textInput(ns(paste0(id, "_search")), NULL,
      placeholder = "Zoeken…", width = "100%"),
    shiny::uiOutput(ns(paste0(id, "_cards"))),
    shiny::div(class = "fm-pager",
      shiny::actionButton(ns(paste0(id, "_prev")), "‹ Vorige"),
      shiny::textOutput(ns(paste0(id, "_page")), inline = TRUE),
      shiny::actionButton(ns(paste0(id, "_next")), "Volgende ›")),
    shiny::tags$details(class = "fm-table-fallback",
      shiny::tags$summary("Volledige tabel bekijken"), table_ui))
}

finance_list_server <- function(input, output, id, data, make_card,
                                page_size = 12L, search = TRUE) {
  page <- shiny::reactiveVal(1L)
  filtered <- shiny::reactive({
    d <- data()
    if (is.null(d)) return(data.frame())
    q <- if (search) input[[paste0(id, "_search")]] else NULL
    if (!is.null(q) && nzchar(trimws(q)) && nrow(d)) {
      q <- tolower(trimws(q))
      keep <- rep(FALSE, nrow(d))
      for (col in d) {
        if (is.atomic(col)) {
          values <- as.character(col)
          if (inherits(col, "Date") || inherits(col, "POSIXt"))
            values <- paste(values, format(col, "%d-%m-%Y"))
          if (is.numeric(col)) values <- paste(values, format(col, decimal.mark = ",", trim = TRUE))
          keep <- keep | (!is.na(values) & grepl(q, tolower(values), fixed = TRUE))
        }
      }
      d <- d[keep, , drop = FALSE]
    }
    d
  })
  pages <- shiny::reactive(max(1L, ceiling(nrow(filtered()) / page_size)))
  current <- shiny::reactive(min(page(), pages()))
  shiny::observeEvent(filtered(), page(1L), ignoreNULL = FALSE)
  shiny::observeEvent(input[[paste0(id, "_prev")]], page(max(1L, current() - 1L)))
  shiny::observeEvent(input[[paste0(id, "_next")]], page(min(pages(), current() + 1L)))
  output[[paste0(id, "_page")]] <- shiny::renderText({
    n <- nrow(filtered())
    if (!n) return("0 resultaten")
    sprintf("%d–%d / %d", (current() - 1L) * page_size + 1L,
            min(current() * page_size, n), n)
  })
  output[[paste0(id, "_cards")]] <- shiny::renderUI({
    d <- filtered()
    if (!nrow(d)) return(shiny::p(class = "fm-muted", "Geen resultaten"))
    ix <- seq.int((current() - 1L) * page_size + 1L, min(current() * page_size, nrow(d)))
    shiny::tagList(lapply(ix, function(i) make_card(d[i, , drop = FALSE])))
  })
}

finance_list_value <- function(row, name, fallback = "") {
  x <- row[[name]]
  if (is.null(x) || !length(x) || is.na(x[1L]) || !nzchar(as.character(x[1L]))) return(fallback)
  x[1L]
}
finance_list_date <- function(x) {
  if (inherits(x, "Date") || inherits(x, "POSIXt")) format(x, "%d-%m-%Y") else as.character(x)
}
finance_list_field <- function(label, value) {
  shiny::div(class = "fm-field", shiny::span(label), shiny::strong(as.character(value)))
}
finance_list_card <- function(title, subtitle, amount, fields = list(), action = NULL,
                              selected = FALSE, positive = FALSE, share = NULL) {
  shiny::tags$details(class = paste("fm-card", if (selected) "fm-selected" else ""),
    shiny::tags$summary(
      shiny::div(class = "fm-card-head",
        shiny::div(class = "fm-card-text", shiny::strong(as.character(title)),
          shiny::span(class = "fm-muted", as.character(subtitle))),
        shiny::strong(class = paste("fm-amount", if (positive) "fm-positive" else ""), as.character(amount)),
        shiny::span(class = "fm-chevron", "⌄")),
      if (!is.null(share)) shiny::div(class = "fm-track",
        shiny::div(style = sprintf("width: %.2f%%", max(0, min(100, share * 100)))))),
    shiny::div(class = "fm-card-detail", fields, action))
}
finance_list_action <- function(session, id, value, label) {
  shiny::tags$button(type = "button", class = "btn btn-outline-secondary fm-action",
    `data-input` = session$ns(id), `data-value` = as.character(value),
    onclick = "Shiny.setInputValue(this.dataset.input, this.dataset.value, {priority:'event'});",
    label)
}
finance_bank_list_data <- function(d) {
  if (is.null(d) || !nrow(d)) return(d)
  if ("Datum" %in% names(d)) d <- d[order(d$Datum, decreasing = TRUE, na.last = TRUE), , drop = FALSE]
  d
}
finance_bank_card <- function(row) {
  v <- function(n, fallback = "") finance_list_value(row, n, fallback)
  direction <- as.character(v("Af Bij"))
  amount <- suppressWarnings(as.numeric(v("Bedrag (EUR)", NA_real_)))
  signed <- suppressWarnings(as.numeric(v("Bedrag_signed", NA_real_)))
  if (is.finite(signed)) amount <- signed else if (is.finite(amount) && direction == "Af") amount <- -abs(amount)
  if (direction == "Bij" && is.finite(amount)) amount <- abs(amount)
  label <- if (!is.finite(amount)) "—" else paste0(if (amount < 0) "− " else "+ ", finance_vl_money(abs(amount)))
  title <- v("Naam / Omschrijving", v("Tegenpartij", "Onbekende tegenpartij"))
  subtitle <- paste(Filter(nzchar, c(finance_list_date(v("Datum")), as.character(v("Tag")))), collapse = " · ")
  extra <- setdiff(names(row), c("Naam / Omschrijving", "Tegenpartij", "Datum", "Bedrag (EUR)", "Bedrag_signed", "Maand", "Tag"))
  fields <- lapply(extra, function(n) {
    x <- v(n)
    if (is.numeric(x) && grepl("Bedrag|Saldo", n)) x <- finance_vl_money(x)
    finance_list_field(n, finance_list_date(x))
  })
  finance_list_card(title, subtitle, label, fields, positive = is.finite(amount) && amount > 0)
}

# Preload the Plotly dependencies before any graph is rendered in Shinylive.
finance_plotly_dependencies <- function() {
  p <- plotly::plot_ly(x = 1, y = 1, type = "scatter", mode = "markers")
  # htmltools is already a dependency of Shiny and Plotly.
  as_tags <- getExportedValue("htmltools", "as.tags")
  find_deps <- getExportedValue("htmltools", "findDependencies")
  shiny::tagList(find_deps(as_tags(p)))
}

# One dedicated container per graph, keeping the original Shiny output ID.
finance_mobile_plot <- function(...) {
  shiny::div(class = "gmc-chart", plotly::plotlyOutput(...))
}

