                actionButton("filter_open_analysis", "Bekijk Analyse & trends", icon = icon("chart-line"),
                             class = "btn btn-primary btn-sm")
              )
            ),
            div(class = "finance-filter-note",
              icon("info-circle"),
              div(strong("Hoe werkt dit samen met de andere filters?"),
                  p("De datumfilter geldt voor Analyse & trends en de brondata op ING en ABN. De lijngrafieken en KPI's op ING, ABN, Kapitaalopbouw en Dashboard hebben hun eigen periodekeuze. Die instellingen blijven onafhankelijk."))
            )
