              ),
              div(class = "panel__body",
                  div(
                    class = "bigbank-legacy",
                    style = bigbank_cols_style,
                    mod_bigbank_ui("bigbank")
                  )
              )
          )
      )
    ),


    ui_panel_tab("Hypotheek", "home", mod_hypotheek_ui("hypotheek", hypotheek_cfg = hypotheek_cfg))
  )
