  ns <- NS(id)

  tagList(
    div(class = "finance-overview finance-abn-overview",
      div(class = "d-flex flex-wrap align-items-center justify-content-between gap-2 mb-3",
        div(
          div(class = "finance-chart-title", "Financiële kerncijfers"),
          div(class = "finance-chart-subtitle", "Alle ABN-rekeningen; bedragen bewegen mee met de periodekeuze")
        ),
        div(class = "finance-abn-period", selectInput(selectize = FALSE, 
          ns("kpi_period"), "Periode",
          choices = c("1 maand" = "1", "6 maanden" = "6", "12 maanden" = "12",
                      "24 maanden" = "24", "30 maanden" = "30", "Alles" = "all"),
          selected = "12", width = "165px"
        ))
      ),
      fluidRow(class = "g-3 mb-4",
        column(4, uiOutput(ns("kpi_saldo"))),
        column(4, uiOutput(ns("kpi_netto"))),
        column(4, uiOutput(ns("kpi_ontwikkeling")))
      ),
      fluidRow(
        class = "g-3 mb-3",
        column(
          6,
          div(class = "finance-chart-card",
            div(class = "finance-chart-heading",
              div(class = "finance-chart-title", "Bij- en afschrijvingen"),
              div(class = "finance-chart-subtitle", "Maandelijkse mutaties op de gezamenlijke rekening")
            ),
            finance_mobile_plot(ns("trend"), height = "390px")
          )
        ),
        column(
          6,
          div(class = "finance-chart-card",
            div(class = "finance-chart-heading",
              div(class = "finance-chart-title", "Kapitaalopbouw"),
              div(class = "finance-chart-subtitle", "Ontwikkeling van de maandelijkse eindsaldi")
            ),
            finance_mobile_plot(ns("cum"), height = "390px")
          )
        )
      ),
      finance_details("Brondata ABN", finance_list_ui(ns, "bank_list", DTOutput(ns("table"))), "Transacties bekijken")
    )
  )
}

# =============================================================================
# SERVER
# =============================================================================
#' @param id               module-id
#' @param data_abn_all     onbewerkte ABN-transacties (data.frame/tibble)
#' @param data_abn_tbl     reactive(): gefilterde ABN-transacties voor tabel
#' @param colors           lijst met kleurmappingen, bv. list(abn = ..., gez = ...)
#' @param initial_months   list(default = n, abn_cum = n)
mod_abn_server <- function(id, data_abn_all, data_abn_tbl, colors, initial_months){
  moduleServer(id, function(input, output, session){

    # ---- Config & events -----------------------------------------------------
    # Event-annotaties + eventuele maanden om te excluden uit gemiddelden
    events_abn  <- cfg_events_to_df(cfg_get("events",  "abn", default = list()))
    exclude_abn <- cfg_get("filters", "exclude_abn",   default = character(0))
    abn_people  <- cfg_get("people",  "abn",           default = character(0))

    # ---- KPI's en gedeelde periodekeuze -------------------------------------
    # Eén periode-instelling voor beide grafieken en de KPI's.
    # Laatste bronmaand is het eindpunt, niet de huidige kalendermaand
    # (zo werkt een historisch bestand ook goed).
    abn_kpi_range <- shiny::reactive({
      df <- data_abn_all()
      dates <- as.Date(df$Datum)
      dates <- dates[!is.na(dates)]
      if (!length(dates)) return(NULL)
      first <- as.Date(lubridate::floor_date(min(dates), "month"))
      last  <- as.Date(lubridate::floor_date(max(dates), "month"))
      choice <- input$kpi_period %||% "12"
      if (identical(choice, "1") &&
          last >= as.Date(lubridate::floor_date(Sys.Date(), "month"))) {
        last <- seq.Date(from = last, by = "-1 month", length.out = 2L)[2L]
      }
      if (last < first) return(NULL)
      n <- suppressWarnings(as.integer(choice))
      if (!is.na(n) && n > 0) {
        first <- max(first, last %m-% lubridate::period(months = n - 1L))
      }
      list(start = first,
           end = as.Date(lubridate::ceiling_date(last, "month") - lubridate::days(1)),
           last_month = last)
    })

    # Alle ABN-rekeningen, dus niet alleen Tag='Gezamenlijk'.
    # Voor het saldo groeperen we op rekeningnummer en NIET op Tag,
    # zodat één rekening met meerdere tags niet dubbel meetelt.
    saldo_abn <- shiny::reactive({
      df <- data_abn_all()
      if (is.null(df) || !nrow(df)) return(NULL)
      df <- df %>%
        dplyr::mutate(.rekening = dplyr::if_else(
          !is.na(.data$Rekening) & nzchar(trimws(as.character(.data$Rekening))),
          as.character(.data$Rekening), as.character(.data$Tag))) %>%
        dplyr::filter(!is.na(.data$Datum), !is.na(.data$`Saldo na mutatie`)) %>%
        dplyr::arrange(.data$Datum) %>%
        dplyr::group_by(.data$.rekening) %>%
        dplyr::slice_tail(n = 1) %>%
        dplyr::ungroup()
      if (!nrow(df)) return(NULL)
      list(value = sum(df$`Saldo na mutatie`), peildatum = max(df$Datum))
    })

    # Netto mutatie: som van bij- minus afschrijvingen op alle ABN-rekeningen.
    # Dit is een banksaldo-mutatie, niet de huishoudelijke spaarquote.
    abn_period_stats <- shiny::reactive({
      rng <- abn_kpi_range()
      if (is.null(rng)) return(NULL)
      df <- data_abn_all() %>%
        dplyr::filter(!is.na(.data$Datum),
                      .data$Datum >= rng$start, .data$Datum <= rng$end)
      if (!nrow(df)) return(NULL)
      delta <- sum(df$Bedrag_signed, na.rm = TRUE)

      # Voor het gemiddelde alleen afgeronde kalendermaanden meenemen.
      # Een lopende maand kan het maandgemiddelde vertekenen.
      last_full <- if (rng$last_month == lubridate::floor_date(Sys.Date(), "month")) {
        rng$last_month %m-% lubridate::period(months = 1)
      } else rng$last_month
      full_months <- if (last_full >= rng$start) {
        seq(as.Date(rng$start), as.Date(last_full), by = "month")
      } else as.Date(character())
      avg <- if (length(full_months)) {
        end_full <- as.Date(lubridate::ceiling_date(last_full, "month") - lubridate::days(1))
        sum(df$Bedrag_signed[df$Datum <= end_full], na.rm = TRUE) / length(full_months)
      } else NA_real_
      # Bij 1 maand: vergelijk de maandmutatie met de maand daarvoor.
      previous_delta <- NA_real_
      if (identical(input$kpi_period, "1")) {
        previous_start <- seq.Date(from = rng$start, by = "-1 month", length.out = 2L)[2L]
        previous_end <- rng$start - 1L
        prev <- data_abn_all() %>%
          dplyr::filter(!is.na(.data$Datum),
                        .data$Datum >= previous_start, .data$Datum <= previous_end)
        if (nrow(prev)) previous_delta <- sum(prev$Bedrag_signed, na.rm = TRUE)
      }
      list(delta = delta, avg = avg, previous_delta = previous_delta,
           n_months = length(full_months),
           start = rng$start, end = rng$end)
    })

    abn_money <- function(value, signed = FALSE) {
      if (length(value) != 1 || is.na(value) || !is.finite(value)) return("—")
      prefix <- if (signed && value > 0) "+ " else if (signed && value < 0) "− " else if (value < 0) "− " else ""
      paste0(prefix, "€ ", format(abs(round(value, 2)), big.mark = ".",
                                  decimal.mark = ",", nsmall = 2, trim = TRUE))
    }
    abn_kpi_card <- function(title, amount, foot, icon_name, positive = NULL) {
      amount_color <- if (is.null(positive)) "#1B3655" else if (positive) "#16806A" else "#B85662"
      div(class = "kpi-card h-100", style = "min-width:0;",
        div(class = "kpi-card-inner",
          div(class = "d-flex align-items-center justify-content-between mb-2",
            span(class = "kpi-card-header", title),
            icon(icon_name, class = "text-muted")
          ),
          div(class = "kpi-amount", style = paste0("color:", amount_color, ";font-size:clamp(21px,2vw,29px);"), amount),
          div(class = "kpi-foot", style = "color:#768397;", foot)
        )
      )
    }

    output$kpi_saldo <- shiny::renderUI({
      s <- saldo_abn()
      abn_kpi_card("Huidig saldo",
                   if (is.null(s)) "—" else abn_money(s$value),
                   if (is.null(s)) "Geen saldodata beschikbaar" else paste0("Laatst bekende standen · ", format(s$peildatum, "%d-%m-%Y")),
                   "wallet")
    })
    output$kpi_ontwikkeling <- shiny::renderUI({
      s <- abn_period_stats()
      v <- if (is.null(s)) NA_real_ else s$delta
      abn_kpi_card("Saldoontwikkeling", abn_money(v, signed = TRUE),
                   if (is.null(s)) "Geen transacties" else if (identical(input$kpi_period, "1"))
                     finance_kpi_month_comparison(v, s$previous_delta)
                   else paste0(format(s$start, "%m-%Y"), " t/m ", format(s$end, "%m-%Y")),
                   "chart-line", if (is.finite(v)) v >= 0 else NULL)
    })
    output$kpi_netto <- shiny::renderUI({
      s <- abn_period_stats()
      v <- if (is.null(s)) NA_real_ else s$avg
      one_month <- identical(input$kpi_period, "1")
      shown <- if (one_month && !is.null(s) && is.finite(s$previous_delta)) v - s$previous_delta else if (one_month) NA_real_ else v
      abn_kpi_card(if (one_month) "Verschil met vorige maand" else "Gem. netto maandmutatie",
                   abn_money(shown, signed = TRUE),
                   if (one_month) {
                     if (is.null(s) || !is.finite(s$previous_delta)) "Vorige maand: onvoldoende gegevens"
                     else paste0("Vorige maand: ", abn_money(s$previous_delta, signed = TRUE))
                   } else if (is.null(s) || s$n_months == 0) "Geen volledige maanden"
                   else paste0("Gemiddelde over ", s$n_months, " volledige maanden"),
                   "exchange-alt", if (is.finite(shown)) shown >= 0 else NULL)
    })

    # Beperk beide grafieken tot dezelfde periode als de KPI's.
    abn_chart_period <- function(plot) {
      rng <- abn_kpi_range()
      if (is.null(rng)) return(plot)
      plot_start <- if (identical(input$kpi_period, "1"))
        seq.Date(from = rng$start, by = "-1 month", length.out = 2L)[2L] else rng$start
      plotly::layout(plot, xaxis = list(range = c(plot_start, rng$end),
                                       rangeselector = list(visible = FALSE)))
    }

    # Iets duidelijkere 0-eurolijn, uitsluitend voor de bij-/afschrijvingen.
    # Plotly tekent deze op y = 0, zonder een extra trace of legenda-item.
    finance_mutation_zeroline <- function(p) {
      p$x$layout$yaxis <- utils::modifyList(
        if (is.list(p$x$layout$yaxis)) p$x$layout$yaxis else list(),
        list(zeroline = TRUE, zerolinecolor = "#9BAAA6", zerolinewidth = 1.6)
      )
      p
    }

    # ---- A) Mutaties per maand (alleen 'Gezamenlijk') ------------------------
    #   - Gebruik onbewerkte brondata (voor eerlijke trend)
    #   - Neem alleen records met Tag == "Gezamenlijk" (case-insensitive)
    transactions_abn_gz <- shiny::reactive({
      data_abn_all() %>%
        dplyr::filter(!is.na(.data$Tag) & grepl("^gezamenlijk$", .data$Tag, ignore.case = TRUE))
    })

    # Samenvatten per maand (helper uit utils); zonder gemiddelde referentielijn
    sums_abn_gz <- shiny::reactive(make_monthly_summaries(
      transactions_abn_gz(),
      exclude_months = exclude_abn
    ))

    output$trend <- renderPlotly({
      # Lege staat netjes afhandelen
      if (!is.list(sums_abn_gz()) || is.null(sums_abn_gz()$monthly) || nrow(sums_abn_gz()$monthly) == 0) {
        return(empty_plot("Geen gezamenlijke transacties gevonden"))
      }

      yr <- pretty_y_range(sums_abn_gz()$monthly$Totaal)

      build_monthly_plot(
        monthly_summary = sums_abn_gz()$monthly,
        means_df        = sums_abn_gz()$means[0, , drop = FALSE], # geen referentielijn
        events          = events_abn,
        initial_months  = initial_months$default,
        y_range         = c(-yr, yr),
        color_map       = c("Gezamenlijk" = colors$gez)
      ) %>%
        finance_modern_plot(date_axis = TRUE) %>%
        abn_chart_period() %>%
        finance_mutation_zeroline()
    })

    # ---- B) Cumulatieve reeks (alle tags) ------------------------------------
    #   - Laatste saldo per maand per Tag, in vaste factor-volgorde uit config
    monthly_last_abn <- shiny::reactive({
      make_monthly_last_saldo(data_abn_all()) %>%
        dplyr::mutate(Tag = factor(.data$Tag, levels = abn_people))
    })

    output$cum <- renderPlotly({
      if (nrow(monthly_last_abn()) == 0) {
        return(empty_plot("Geen data om te tonen"))
      }

      build_cumulative_plot(
        monthly_last      = monthly_last_abn(),
        events            = events_abn,
        initial_months    = initial_months$abn_cum,
        show_point_labels = FALSE,
        color_map         = colors$abn
      ) %>%
        finance_modern_plot(date_axis = TRUE) %>%
        abn_chart_period()
    })

    # ---- C) Brondata-tabel (gefilterde variant) ------------------------------
    #   - Verberg helperkolommen die niet in de tabel hoeven
    finance_list_server(input, output, "bank_list",
      shiny::reactive(finance_bank_list_data(data_abn_tbl())), finance_bank_card)

    output$table <- finance_renderDT({
      df <- data_abn_tbl()
      if (is.null(df) || nrow(df) == 0) {
        return(finance_tx_table(df))  # dezelfde compacte weergave voor lege staat
      }

      df <- df %>%
        dplyr::select(-dplyr::any_of(c("Bedrag_signed", "Maand")))

      finance_tx_table(df)
    })
  })
}

