#' @param id       module-id
#' @param data_ing reactive(): gefilterde ING-transacties
#' @param data_abn reactive(): gefilterde ABN-transacties
mod_analyse_server <- function(id, data_ing, data_abn, category_version = NULL){
  moduleServer(id, function(input, output, session){
    ns <- session$ns

    # ---- Constantes / parameters ---------------------------------------------
    TOP_N_MOVERS <- 8
    # Kies een leesbare maandafstand voor de tijdas van de categoriegrafiek.
    # Plotly gebruikt maandintervallen in de vorm M1, M3, M6, M12.
    analyse_month_axis <- function(datums) {
      datums <- as.Date(datums)
      datums <- datums[!is.na(datums)]
      if (length(datums) < 2L) return(list(dtick = "M1"))

      maanden <- (as.integer(format(max(datums), "%Y")) -
                    as.integer(format(min(datums), "%Y"))) * 12L +
                 as.integer(format(max(datums), "%m")) -
                 as.integer(format(min(datums), "%m")) + 1L
      stap <- if (maanden <= 15L) 1L else if (maanden <= 36L) 3L else if (maanden <= 72L) 6L else 12L
      list(dtick = paste0("M", stap))
    }

    # ---- Gecombineerde gefilterde transacties --------------------------------
    combined_tx <- reactive({
      dplyr::bind_rows(
        data_ing() %>% dplyr::mutate(Bank = "ING"),
        data_abn() %>% dplyr::mutate(Bank = "ABN")
      )
    })

    # ---- Filter voor de heatmaps ----------------------------------------------
    # Bank-totalen en afzonderlijke rekeningnummers uit de actuele brondata.
    # Andere analyses op dit werkblad behouden hun eigen (bestaande) filters.
    observe({
      tx <- combined_tx()
      keuzes <- c("Alle rekeningen" = "all",
                   "ING · alle rekeningen" = "bank:ING",
                   "ABN · alle rekeningen" = "bank:ABN")

      if (is.data.frame(tx) && nrow(tx) &&
          all(c("Bank", "Rekening") %in% names(tx))) {
        paren <- unique(data.frame(
          Bank = as.character(tx$Bank),
          Rekening = trimws(as.character(tx$Rekening)),
          stringsAsFactors = FALSE
        ))
        paren <- paren[!is.na(paren$Rekening) & nzchar(paren$Rekening) &
                         paren$Bank %in% c("ING", "ABN"), , drop = FALSE]
        paren <- paren[order(paren$Bank, paren$Rekening), , drop = FALSE]
        if (nrow(paren)) {
          # De YAML-mapping wordt ook bij de import gebruikt: tags -> accounts.
          # Alleen het zichtbare label wijzigen; de filterwaarde blijft gelijk.
          rekeninghouders <- cfg_get("tags", "accounts", default = list())
          naam_per_rekening <- character()
          if (is.list(rekeninghouders) && length(rekeninghouders)) {
            sleutels <- names(rekeninghouders)
            if (!is.null(sleutels)) {
              normaliseer_rekening <- function(x) {
                toupper(gsub("[^A-Z0-9]", "", as.character(x)))
              }
              naam_per_rekening <- vapply(rekeninghouders, function(item) {
                waarde <- unlist(item, use.names = FALSE)
                if (!length(waarde) || is.na(waarde[1])) "" else trimws(as.character(waarde[1]))
              }, character(1))
              names(naam_per_rekening) <- normaliseer_rekening(sleutels)
            }
          }

          opties <- paste0("account:", paren$Bank, ":", paren$Rekening)
          labels <- paste(paren$Bank, paren$Rekening, sep = " · ")
          if (length(naam_per_rekening)) {
            rekening_sleutels <- toupper(gsub("[^A-Z0-9]", "", paren$Rekening))
            houders <- unname(naam_per_rekening[rekening_sleutels])
            bekend <- !is.na(houders) & nzchar(houders)
            labels[bekend] <- paste0(labels[bekend], " (", houders[bekend], ")")
          }
          names(opties) <- labels
          keuzes <- c(keuzes, opties)
        }
      }

      huidig <- isolate(input$heat_rekening)
      if (is.null(huidig) || !huidig %in% unname(keuzes)) huidig <- "all"
      updateSelectInput(session, "heat_rekening",
                        choices = keuzes, selected = huidig)
    })

    heat_transacties <- reactive({
      # Geen categorisering nodig: voor kasstromen telt iedere mutatie mee.
      tx <- combined_tx()
      keuze <- input$heat_rekening
      if (is.null(keuze) || identical(keuze, "all") ||
          is.null(tx) || !nrow(tx)) return(tx)

      if (startsWith(keuze, "bank:")) {
        bank <- substring(keuze, 6L)
        return(dplyr::filter(tx, .data$Bank == bank))
      }
      if (startsWith(keuze, "account:")) {
        sleutel <- substring(keuze, 9L)
        return(dplyr::filter(tx,
          paste(.data$Bank, trimws(as.character(.data$Rekening)), sep = ":") == sleutel))
      }
      tx
    })

    # Categorisering voorbereid op laptop; periodieke herkenning blijft datumafhankelijk.
    combined_tx_cat <- reactive({
      if (is.function(category_version)) category_version()
      finance_prepared_analysis(combined_tx(), FINANCE_SNAPSHOT$prepared$analyse)
    })

    # ---- Top movers (tegenpartij) --------------------------------------------
    monthly_cp <- reactive(monthly_by_counterparty(combined_tx()))
    movers_cp  <- reactive(top_movers_counterparty(monthly_cp(), top = TOP_N_MOVERS))

    output$movers_plot <- plotly::renderPlotly({
      finance_modern_plot(local({
      build_movers_bar(movers_cp())

      }), date_axis = FALSE)
    })

    # ---- Monthly by category (gefilterd) -------------------------------------
    monthly_cat_f <- reactive({
      df <- combined_tx_cat()
      if (is.null(df) || !nrow(df)) {
        return(tibble::tibble(Maand = as.Date(character()),
                              Category = character(),
                              Uitgaven = double(),
                              Inkomsten = double()))
      }

      monthly_by_category(df) %>%
        dplyr::mutate(
          Category = as.character(.data$Category),
          Category = ifelse(is.na(.data$Category) | .data$Category == "", "Onbekend", .data$Category)
        )
    })

    # ---- Maandtotalen voor de heatmap --------------------------------------
    # Deze heatmap toont ALLE werkelijke rekeningmutaties, inclusief interne
    # overboekingen en sparen/beleggen. De richting (Af/Bij) is leidend, niet
    # de categorisering. Zo blijft zichtbaar wat er op iedere rekening in en
    # uit gaat. De overige analyses behouden hun bestaande categoriefilters.
    heat_maand <- reactive({
      tx <- heat_transacties()
      if (is.null(tx) || !nrow(tx)) {
        return(tibble::tibble(Maand = as.Date(character()),
                              Inkomsten = numeric(), Uitgaven = numeric()))
      }
      tx |>
        dplyr::filter(
          !is.na(.data$Maand),
          .data$`Af Bij` %in% c("Af", "Bij"),
          is.finite(.data$`Bedrag (EUR)`)
        ) |>
        dplyr::group_by(.data$Maand) |>
        dplyr::summarise(
          Inkomsten = sum(abs(.data$`Bedrag (EUR)`[.data$`Af Bij` == "Bij"]), na.rm = TRUE),
          Uitgaven = sum(abs(.data$`Bedrag (EUR)`[.data$`Af Bij` == "Af"]), na.rm = TRUE),
          .groups = "drop"
        ) |>
        dplyr::arrange(.data$Maand)
    })

    maanden_kort <- c("jan", "feb", "mrt", "apr", "mei", "jun",
                      "jul", "aug", "sep", "okt", "nov", "dec")

    euro_exact <- function(x) {
      paste0("€ ", formatC(x, format = "f", digits = 2,
                           big.mark = ".", decimal.mark = ","))
    }

    heatmap_jaar_maand <- function(d, kolom, kleur, source) {
      shiny::validate(shiny::need(nrow(d) > 0, "Geen transacties beschikbaar"))

      d$Jaar <- as.integer(format(d$Maand, "%Y"))
      d$MaandNum <- as.integer(format(d$Maand, "%m"))
      jaren <- sort(unique(d$Jaar))
      waarden <- matrix(NA_real_, nrow = length(jaren), ncol = 12)
      for (i in seq_len(nrow(d))) {
        waarden[match(d$Jaar[i], jaren), d$MaandNum[i]] <- d[[kolom]][i]
      }

      # Elk aanwezig maandbedrag staat letterlijk in zijn vakje;
      # maanden zonder transacties blijven leeg (niet ten onrechte € 0).
      annotaties <- list()
      for (j in seq_along(jaren)) {
        for (m in 1:12) {
          bedrag <- waarden[j, m]
          if (!is.finite(bedrag)) next
          annotaties[[length(annotaties) + 1L]] <- list(
            x = m, y = jaren[j], xref = "x", yref = "y",
            text = euro_exact(bedrag), showarrow = FALSE,
            font = list(size = 9, color = "#172B42")
          )
        }
      }

      hover <- matrix("", nrow = length(jaren), ncol = 12)
      for (j in seq_along(jaren)) {
        for (m in 1:12) {
          if (is.finite(waarden[j, m])) {
            hover[j, m] <- paste0(maanden_kort[m], " ", jaren[j],
                                  "<br>", kolom, ": <b>",
                                  euro_exact(waarden[j, m]), "</b>")
          }
        }
      }

      # Begrens uitsluitend de kleurenschaal op het 95e percentiel.
      # De werkelijke bedragen blijven ongewijzigd in de vakjes en hover.
      geldige_bedragen <- waarden[is.finite(waarden)]
      kleur_max <- if (length(geldige_bedragen)) {
        as.numeric(stats::quantile(geldige_bedragen, probs = 0.95,
                                   na.rm = TRUE, names = FALSE))
      } else {
        1
      }
      kleur_max <- max(kleur_max, 1)

      plotly::plot_ly(
        source = source,
        x = 1:12, y = jaren, z = waarden,
        text = hover, type = "heatmap",
        colorscale = list(c(0, "#F1F5F9"), c(1, kleur)),
        zmin = 0, zmax = kleur_max, zauto = FALSE,
        hovertemplate = "%{text}<extra></extra>",
        hoverongaps = FALSE, showscale = FALSE
      ) |>
        plotly::layout(
          xaxis = list(title = "", tickmode = "array", tickvals = 1:12,
                       ticktext = maanden_kort, range = c(0.5, 12.5), fixedrange = FALSE),
          yaxis = list(title = "", tickmode = "array", tickvals = jaren,
                       autorange = "reversed", fixedrange = FALSE),
          annotations = annotaties,
          margin = list(l = 52, r = 12, t = 16, b = 38),
          paper_bgcolor = "rgba(0,0,0,0)",
          plot_bgcolor = "rgba(0,0,0,0)"
        ) |>
        plotly::config(displayModeBar = FALSE, responsive = TRUE) |>
        plotly::event_register("plotly_click")
    }

    # Houd klikgebeurtenissen gescheiden van andere Plotly-grafieken.
    heat_source <- ns("heat_geldstroom_selectie")
    heat_selectie <- shiny::reactiveVal(NULL)
    heat_plot_geregistreerd <- shiny::reactiveVal(FALSE)

    # Een selectie hoort altijd bij de actuele rekening en geldstroom.
    shiny::observeEvent(list(input$heat_rekening, input$heat_type), {
      heat_selectie(NULL)
      heat_plot_geregistreerd(FALSE)
    }, ignoreInit = TRUE)

    shiny::observeEvent(
      {
        shiny::req(heat_plot_geregistreerd())
        plotly::event_data("plotly_click", source = heat_source, priority = "event")
      },
      {
        klik <- plotly::event_data("plotly_click", source = heat_source)
        if (is.null(klik) || !nrow(klik)) return()
        maand <- suppressWarnings(as.integer(as.character(klik$x[[1]])))
        jaar <- suppressWarnings(as.integer(as.character(klik$y[[1]])))
        if (is.na(maand) || !maand %in% 1:12 || is.na(jaar)) return()
        eerste <- as.Date(sprintf("%04d-%02d-01", jaar, maand))
        if (is.na(eerste) || !eerste %in% heat_maand()$Maand) return()
        heat_selectie(eerste)
      },
      ignoreInit = TRUE
    )

    # Gebruik exact dezelfde bron en rekeningselectie als de heatmap.
    heat_detail_rows <- shiny::reactive({
      maand <- heat_selectie()
      shiny::req(maand)
      richting <- if (identical(input$heat_type, "Inkomsten")) "Bij" else "Af"
      tx <- heat_transacties()
      shiny::req(is.data.frame(tx))
      tx |>
        dplyr::filter(
          !is.na(.data$Datum),
          as.Date(.data$Datum) >= maand,
          as.Date(.data$Datum) < seq(maand, by = "month", length.out = 2L)[2L],
          .data$`Af Bij` == richting,
          is.finite(.data$`Bedrag (EUR)`)
        ) |>
        dplyr::arrange(dplyr::desc(.data$Datum))
    })

    output$heat_details <- shiny::renderUI({
      maand <- heat_selectie()
      if (is.null(maand)) {
        return(shiny::div(
          style = "color:#71887C; padding:8px 0;",
          "Klik op een maandvakje in de heatmap om de onderliggende transacties te bekijken. Open op een touchscreen eerst Vergroten."
        ))
      }
      d <- heat_detail_rows()
      soort <- if (identical(input$heat_type, "Inkomsten")) "Inkomsten" else "Uitgaven"
      shiny::tagList(
        shiny::div(
          style = "display:flex; flex-wrap:wrap; gap:12px; align-items:center; justify-content:space-between; margin-bottom:12px;",
          shiny::div(
            shiny::strong(paste0(soort, " · ", maanden_kort[as.integer(format(maand, "%m"))], " ", format(maand, "%Y"))),
            shiny::span(
              style = "margin-left:10px; color:#71887C;",
              paste0(nrow(d), " transacties · ", euro_exact(sum(abs(d$`Bedrag (EUR)`), na.rm = TRUE)))
            )
          ),
          shiny::actionButton(ns("heat_clear"), "Selectie wissen", icon = shiny::icon("xmark"), class = "btn-default btn-sm")
        ),
        DT::DTOutput(ns("heat_detail_tabel"))
      )
    })

    shiny::observeEvent(input$heat_clear, {heat_selectie(NULL)})

    output$heat_detail_tabel <- finance_renderDT({
      df <- heat_detail_rows()
      kolommen <- c("Datum", "Bank", "Rekening", "Naam / Omschrijving",
                     "Tegenrekening", "Af Bij", "Bedrag (EUR)", "Mededelingen")
      zichtbaar <- df[, intersect(kolommen, names(df)), drop = FALSE]
      finance_tx_table(zichtbaar)
    })

    output$heat_geldstroom <- plotly::renderPlotly({
      soort <- input$heat_type
      if (is.null(soort) || !soort %in% c("Uitgaven", "Inkomsten")) {
        soort <- "Uitgaven"
      }
      kleur <- if (soort == "Uitgaven") "#D99677" else "#4C9F86"
      p <- heatmap_jaar_maand(heat_maand(), soort, kleur, source = heat_source)
      heat_plot_geregistreerd(TRUE)
      p
    })

    # ---- Categorie-select updaten --------------------------------------------
    observe({
      df <- monthly_cat_f()

      cats <- tryCatch({
        if (!is.data.frame(df) || !"Category" %in% names(df)) character(0)
        else sort(unique(as.character(df$Category)))
      }, error = function(e) character(0))

      # huidige selectie behouden indien mogelijk
      sel <- isolate(input$cat_select)
      if (is.null(sel) || !(sel %in% c("Alle categorieën", cats))) {
        sel <- "Alle categorieën"
      }

      updateSelectizeInput(
        session, "cat_select",
        choices  = c("Alle categorieën", cats),
        selected = sel,
        server   = FALSE
      )
    })

    # ---- Top movers – categorieën (Δ t.o.v. vorige maand) --------------------
    movers_cat <- reactive({
      monthly_cat_f() %>%
        dplyr::group_by(.data$Category) %>%
        dplyr::arrange(.data$Maand, .by_group = TRUE) %>%
        dplyr::mutate(
          Uitgaven_lag = dplyr::lag(.data$Uitgaven),
          Delta        = .data$Uitgaven - .data$Uitgaven_lag
        ) %>%
        dplyr::ungroup() %>%
        dplyr::filter(.data$Maand == max(.data$Maand, na.rm = TRUE), !is.na(.data$Delta)) %>%
        dplyr::arrange(dplyr::desc(abs(.data$Delta))) %>%
        dplyr::mutate(Richting = ifelse(.data$Delta >= 0, "↑ duurder", "↓ goedkoper")) %>%
        head(TOP_N_MOVERS)
    })

    output$movers_cat_plot <- plotly::renderPlotly({
      finance_modern_plot(local({
      df_cat <- movers_cat() %>%
        dplyr::mutate(NormNaam = as.character(.data$Category))  # alias t.b.v. build_movers_bar()

      build_movers_bar(df_cat) %>%
        plotly::layout(title = list(text = "Top movers – categorie"))

      }), date_axis = FALSE)
    })

    # ---- Per categorie (lijn) of alle (stacked) -------------------------------
    output$cat_month_plot <- plotly::renderPlotly({
      finance_modern_plot(local({
      dat <- monthly_cat_f()
      if (!nrow(dat)) return(empty_plot("Geen data om te tonen"))

      # 1) Eén categorie → twee lijnen (Uitgaven & Inkomsten)
      if (!is.null(input$cat_select) && input$cat_select != "Alle categorieën") {
        d1 <- dat %>%
          dplyr::filter(.data$Category == input$cat_select) %>%
          dplyr::arrange(.data$Maand)

        cols2 <- safe_brewer(2, pal = "Set3")

        return(
          plotly::plot_ly(type = "scatter", mode = "lines+markers") %>%
            plotly::add_trace(
              data = d1, x = ~Maand, y = ~Uitgaven, name = "Uitgaven",
              type = "scatter", mode = "lines+markers",
              line = list(shape = "spline", smoothing = 0.5, width = 1.4, color = cols2[1]),
              marker = list(size = 5, color = cols2[1]),
              hovertemplate = "%{x|%b %Y}<br>Uitgaven: € %{y:,.0f}<extra></extra>"
            ) %>%
            plotly::add_trace(
              data = d1, x = ~Maand, y = ~Inkomsten, name = "Inkomsten",
              type = "scatter", mode = "lines+markers",
              line = list(shape = "spline", smoothing = 0.5, width = 1.4, color = cols2[2]),
              marker = list(size = 5, color = cols2[2]),
              hovertemplate = "%{x|%b %Y}<br>Inkomsten: € %{y:,.0f}<extra></extra>"
            ) %>%
            plotly::layout(
              title = list(text = paste0("Verloop – ", input$cat_select)),
              hovermode = "x unified",
              xaxis = list(
                title = "", type = "date", tickformat = "%b %Y",
                dtick = analyse_month_axis(d1$Maand)$dtick, tickangle = 0,
                showspikes = TRUE, spikemode = "across", spikesnap = "cursor"
              ),
              yaxis = list(title = "", tickprefix = "€ ", separatethousands = TRUE, rangemode = "tozero"),
              legend = list(orientation = "h", x = 0, y = 1.12),
              margin = list(t = 50, r = 20)
            )
        )
      }

      # 2) Alle categorieën → stacked bars (alleen Uitgaven), top-N + "Overig"
      totals <- dat %>%
        dplyr::group_by(.data$Category) %>%
        dplyr::summarise(Total = sum(.data$Uitgaven, na.rm = TRUE), .groups = "drop") %>%
        dplyr::arrange(dplyr::desc(.data$Total))

      keep <- head(totals$Category, TOP_N_MOVERS)

      dat2 <- dat %>%
        dplyr::mutate(Category2 = ifelse(.data$Category %in% keep, .data$Category, "Overig")) %>%
        dplyr::group_by(.data$Maand, .data$Category2) %>%
        dplyr::summarise(Uitgaven = sum(.data$Uitgaven, na.rm = TRUE), .groups = "drop") %>%
        dplyr::arrange(.data$Maand)

      labels <- sort(unique(dat2$Category2))
      dat2   <- dat2 %>% dplyr::mutate(Category2 = factor(.data$Category2, levels = labels))
      cols   <- safe_brewer(length(labels), pal = "Set3")

      plotly::plot_ly(
        dat2,
        x = ~Maand, y = ~Uitgaven,
        color = ~Category2, colors = cols,
        type = "bar",
        hovertemplate = "%{x|%b %Y}<br>%{color}<br>Uitgaven: € %{y:,.0f}<extra></extra>"
      ) %>%
        plotly::layout(
          barmode = "stack",
          hovermode = "x unified",
          xaxis = list(
            title = "", type = "date", tickformat = "%b %Y",
            dtick = analyse_month_axis(dat2$Maand)$dtick, tickangle = 0,
            showspikes = TRUE, spikemode = "across", spikesnap = "cursor"
          ),
          yaxis = list(title = "", tickprefix = "€ ", separatethousands = TRUE, rangemode = "tozero"),
          legend = list(orientation = "h", x = 0, y = 1.12),
          margin = list(t = 50, r = 20)
        )

      }), date_axis = FALSE)
    })
  })
}

