# Centrale cockpit: vergelijkingen over VOLLEDIGE kalendermaanden.
# De categoriale definitie is bewust gelijk aan Analyse & trends.

finance_dashboard_money <- function(x, signed = FALSE) {
  if (length(x) != 1L || !is.finite(x)) return("—")
  s <- if (x < 0) "− " else if (signed && x > 0) "+ " else ""
  paste0(s, "€ ", format(round(abs(x), 0), big.mark = ".", decimal.mark = ",", trim = TRUE))
}
finance_dashboard_pct <- function(x) {
  if (length(x) != 1L || !is.finite(x)) return("—")
  paste0(format(round(x, 1), nsmall = 1, decimal.mark = ",", trim = TRUE), "%")
}
finance_dashboard_change <- function(current, previous, type = "money") {
  if (!is.finite(current) || !is.finite(previous)) return("Vergelijking niet beschikbaar")
  if (identical(type, "points")) {
    v <- current - previous
    return(paste0(if (v > 0) "+ " else if (v < 0) "− " else "", 
                  format(round(abs(v), 1), decimal.mark = ",", nsmall = 1), " procentpunt"))
  }
  if (identical(type, "percent")) {
    if (previous == 0) return("Geen vergelijkbare basis")
    v <- (current / previous - 1) * 100
    return(paste0(if (v > 0) "+ " else if (v < 0) "− " else "",
                  format(round(abs(v), 1), decimal.mark = ",", nsmall = 1), "%"))
  }
  finance_dashboard_money(current - previous, signed = TRUE)
}
finance_dashboard_card <- function(title, amount, comparison, detail, positive = NULL, icon_name = "chart-line") {
  clr <- if (is.null(positive) || is.na(positive)) "" else if (positive) " dashboard-delta--good" else " dashboard-delta--bad"
  shiny::div(class = "dashboard-kpi",
    shiny::div(class = "dashboard-kpi__top", shiny::span(title), shiny::icon(icon_name)),
    shiny::div(class = "dashboard-kpi__value", amount),
    shiny::div(class = paste0("dashboard-delta", clr), comparison),
    shiny::div(class = "dashboard-kpi__detail", detail)
  )
}
finance_dashboard_months <- function(end_month, n) {
  if (length(end_month) != 1 || is.na(end_month)) return(as.Date(character()))
  seq.Date(from = as.Date(end_month), by = "-1 month", length.out = n) |> rev()
}
finance_dashboard_sum_period <- function(df, months) {
  x <- df[df$Maand %in% months, , drop = FALSE]
  if (!length(months) || nrow(x) != length(months))
    return(c(Inkomsten = NA_real_, Uitgaven = NA_real_, Netto = NA_real_, Spaarquote = NA_real_))
  inc <- sum(x$Inkomsten); out <- sum(x$Uitgaven)
  c(Inkomsten = inc, Uitgaven = out, Netto = inc - out,
    Spaarquote = if (inc > 0) 100 * (inc - out) / inc else NA_real_)
}

