mod_dashboard_server <- function(id, data_ing_all, data_abn_all, category_version = NULL) {
  shiny::moduleServer(id, function(input, output, session) {
    # Data-reactives vanuit app_server volgen het bestaande upload-refreshsignaal.
    raw <- shiny::reactive({
      dplyr::bind_rows(
        data_ing_all() %>% dplyr::mutate(Bank = "ING"),
        data_abn_all() %>% dplyr::mutate(Bank = "ABN")
      ) %>% dplyr::filter(!is.na(.data$Datum))
    })
    categorized <- shiny::reactive({
      if (is.function(category_version)) category_version()
      FINANCE_SNAPSHOT$prepared$dashboard_categorized
    })
    signal_version <- shiny::reactiveVal(0L)
    transaction_signals <- shiny::reactive({
      FINANCE_SNAPSHOT$prepared$dashboard_signals
    })
    assessed_signals <- shiny::reactive({
      signal_version()
      d <- transaction_signals()
      if (!nrow(d)) { d$Status <- character(); return(d) }
      statuses <- finance_signal_statuses()
      d$Status <- "Nieuw"
      ix <- match(d$signaal_id, statuses$signaal_id)
      use <- !is.na(ix)
      d$Status[use] <- statuses$status[ix[use]]
      d
    })
    visible_signals <- shiny::reactive({
      d <- assessed_signals()
      if (!isTRUE(input$show_handled)) d <- d[d$Status != "Afgehandeld", , drop = FALSE]
      d
    })
    output$signal_table <- finance_renderDT({
      d <- visible_signals()
      if (!nrow(d)) return(DT::datatable(data.frame(Melding = "Geen openstaande transactiesignalen"),
                                           options = list(dom = "t"), rownames = FALSE, selection = "none"))
      view <- data.frame(Datum = format(d$Datum, "%d-%m-%Y"),
                         Type = d$Type, Signaal = d$Titel, Status = d$Status,
                         check.names = FALSE)
      DT::datatable(view, rownames = FALSE, selection = "single",
        options = list(pageLength = 8, lengthChange = FALSE, order = list(list(0, "desc")),
                       scrollX = TRUE, language = list(search = "Zoeken:")))
    })
    selected_signal <- shiny::reactive({
      ix <- input$signal_table_rows_selected
      d <- visible_signals()
      if (length(ix) != 1L || !nrow(d) || ix < 1L || ix > nrow(d)) return(NULL)
      d[ix, , drop = FALSE]
    })
    output$signal_detail <- shiny::renderUI({
      x <- selected_signal()
      if (is.null(x)) return(shiny::p(class = "dashboard-note", "Selecteer een melding om de details te bekijken."))
      shiny::div(class = "dashboard-signal-detail",
        shiny::strong(x$Titel[[1]]), shiny::p(x$Toelichting[[1]]),
        shiny::span(class = "dashboard-panel__sub", paste("Status:", x$Status[[1]])))
    })

    flows <- shiny::reactive({
      d <- categorized()
      if (!nrow(d)) return(data.frame(Maand = as.Date(character()), Inkomsten = numeric(), Uitgaven = numeric(), Netto = numeric(), Spaarquote = numeric()))
      d %>%
        dplyr::filter(!is.na(.data$Maand),
          !as.character(.data$Category) %in% c("Overboeking (eigen)", "Sparen/Beleggen")) %>%
        dplyr::group_by(.data$Maand) %>%
        dplyr::summarise(Inkomsten = sum(dplyr::if_else(.data$`Af Bij` == "Bij", .data$`Bedrag (EUR)`, 0), na.rm = TRUE),
                         Uitgaven = sum(dplyr::if_else(.data$`Af Bij` == "Af", .data$`Bedrag (EUR)`, 0), na.rm = TRUE), .groups = "drop") %>%
        dplyr::mutate(Netto = .data$Inkomsten - .data$Uitgaven,
          Spaarquote = dplyr::if_else(.data$Inkomsten > 0, 100 * .data$Netto / .data$Inkomsten, NA_real_)) %>%
        dplyr::arrange(.data$Maand)
    })
    # Referentie = laatst beschikbare AFGESLOTEN maand met transacties.
    # De peildatum is zichtbaar, zodat verouderde exports niet als actueel gelden.
    ref_month <- shiny::reactive({
      months <- as.Date(flows()$Maand)
      last_closed <- seq.Date(from = lubridate::floor_date(Sys.Date(), "month"), by = "-1 month", length.out = 2L)[2]
      valid <- months[!is.na(months) & months <= last_closed]
      if (!length(valid)) return(as.Date(NA))
      max(valid)
    })
    selection <- shiny::reactive({
      n <- as.integer(input$period %||% "12")
      last <- ref_month()
      if (is.na(last)) return(NULL)
      current <- finance_dashboard_months(last, n)
      previous <- finance_dashboard_months(seq.Date(from = current[1], by = "-1 month", length.out = 2)[2], n)
      list(n = n, current = current, previous = previous,
           now = finance_dashboard_sum_period(flows(), current),
           before = finance_dashboard_sum_period(flows(), previous))
    })
    output$date_note <- shiny::renderUI({
      s <- selection()
      if (is.null(s)) return(shiny::div(class = "dashboard-note", "Er zijn nog geen volledige kalendermaanden beschikbaar."))
      shiny::div(class = "dashboard-note",
        paste0("Periode: ", format(min(s$current), "%m-%Y"), " t/m ", format(max(s$current), "%m-%Y"),
               " · vergelijking met de voorafgaande ", s$n, if (s$n == 1) " maand" else " maanden"))
    })
    # Historisch banksaldo: op iedere maandultimo laatste stand per afzonderlijke
    # rekening. Geen optelling van uitsluitend rekeningen met transacties in die maand.
    saldo_monthly <- shiny::reactive({
      d <- raw() %>% dplyr::filter(!is.na(.data$`Saldo na mutatie`), !is.na(.data$Rekening)) %>%
        dplyr::mutate(Account = paste(.data$Bank, .data$Rekening, sep = "::")) %>%
        dplyr::arrange(.data$Datum)
      if (!nrow(d)) return(data.frame(Maand = as.Date(character()), Saldo = numeric()))
      accounts <- unique(d$Account)
      months <- seq.Date(from = lubridate::floor_date(min(d$Datum), "month"),
                         to = lubridate::floor_date(max(d$Datum), "month"), by = "month")
      result <- lapply(months, function(m) {
        next_month <- seq.Date(from = m, by = "1 month", length.out = 2)[2]
        avail <- d[d$Datum < next_month, , drop = FALSE]
        # Geen onvolledige totaalstand als een rekening nog geen historisch saldo heeft.
        if (!all(accounts %in% avail$Account)) return(NA_real_)
        last <- avail %>% dplyr::group_by(.data$Account) %>%
          dplyr::slice_tail(n = 1) %>% dplyr::ungroup()
        sum(last$`Saldo na mutatie`, na.rm = TRUE)
      })
      data.frame(Maand = months, Saldo = as.numeric(unlist(result)))
    })
    saldo_growth <- shiny::reactive({
      s <- selection(); d <- saldo_monthly()
      if (is.null(s) || !nrow(d)) return(c(now = NA_real_, previous = NA_real_))
      at <- function(month) {
        x <- d$Saldo[match(month, d$Maand)]
        if (!length(x) || !is.finite(x)) return(NA_real_)
        x
      }
      baseline <- seq.Date(from = s$current[1], by = "-1 month", length.out = 2)[2]
      older <- seq.Date(from = s$previous[1], by = "-1 month", length.out = 2)[2]
      c(now = at(tail(s$current, 1)) - at(baseline),
        previous = at(tail(s$previous, 1)) - at(older))
    })
    output$kpi_netto <- shiny::renderUI({
      s <- selection(); if (is.null(s)) return(finance_dashboard_card("Netto overgehouden", "—", "Onvoldoende data", "Volledige maanden", icon_name = "wallet"))
      a <- unname(s$now["Netto"]); b <- unname(s$before["Netto"])
      finance_dashboard_card("Netto overgehouden", finance_dashboard_money(a),
        finance_dashboard_change(a, b), "t.o.v. vorige periode",
        if (is.finite(a) && is.finite(b)) a >= b else NULL, "wallet")
    })
    output$kpi_spaarquote <- shiny::renderUI({
      s <- selection(); if (is.null(s)) return(finance_dashboard_card("Spaarquote", "—", "Onvoldoende data", "", icon_name = "piggy-bank"))
      a <- unname(s$now["Spaarquote"]); b <- unname(s$before["Spaarquote"])
      finance_dashboard_card("Gem. spaarquote", finance_dashboard_pct(a),
        finance_dashboard_change(a, b, "points"), "t.o.v. vorige periode",
        if (is.finite(a) && is.finite(b)) a >= b else NULL, "piggy-bank")
    })
    output$kpi_uitgaven <- shiny::renderUI({
      s <- selection(); if (is.null(s)) return(finance_dashboard_card("Totale uitgaven", "—", "Onvoldoende data", "", icon_name = "credit-card"))
      a <- unname(s$now["Uitgaven"]); b <- unname(s$before["Uitgaven"])
      finance_dashboard_card("Totale uitgaven", finance_dashboard_money(a),
        finance_dashboard_change(a, b, "percent"), "t.o.v. vorige periode",
        if (is.finite(a) && is.finite(b)) a <= b else NULL, "credit-card")
    })
    output$kpi_saldo <- shiny::renderUI({
      gr <- saldo_growth(); a <- unname(gr["now"]); b <- unname(gr["previous"])
      finance_dashboard_card("Groei banksaldo", finance_dashboard_money(a, signed = TRUE),
        finance_dashboard_change(a, b), "ING + ABN · t.o.v. vorige periode",
        if (is.finite(a) && is.finite(b)) a >= b else NULL, "chart-line")
    })
    output$flow_caption <- shiny::renderText({
      s <- selection(); if (is.null(s)) return("")
      if (s$n == 1) "Laatste 6 maanden voor de trend" else paste0("Laatste ", s$n, " maanden")
    })
    output$flow_plot <- plotly::renderPlotly({
      s <- selection(); if (is.null(s)) return(empty_plot("Nog geen volledige maandgegevens"))
      shown <- finance_dashboard_months(tail(s$current, 1), max(6L, s$n))
      df <- flows() %>% dplyr::filter(.data$Maand %in% shown)
      if (!nrow(df)) return(empty_plot("Geen financiële mutaties gevonden"))
      p <- plotly::plot_ly(df, x = ~Maand) %>%
        plotly::add_bars(y = ~Inkomsten, name = "Inkomsten", marker = list(color = "#087C68"),
          hovertemplate = "Inkomsten: € %{y:,.2f}<extra></extra>") %>%
        plotly::add_bars(y = ~Uitgaven, name = "Uitgaven", marker = list(color = "#D88974"),
          hovertemplate = "Uitgaven: € %{y:,.2f}<extra></extra>") %>%
        plotly::add_trace(y = ~Netto, name = "Netto overgehouden", type = "scatter", mode = "lines+markers",
          line = list(color = "#426C98", width = 1.8, shape = "spline", smoothing = .5),
          marker = list(color = "#426C98", size = 5),
          hovertemplate = "Netto: € %{y:,.2f}<extra></extra>") %>%
        plotly::layout(barmode = "group", hovermode = "x unified",
          xaxis = list(type = "date", tickformat = "%b %Y", dtick = if (length(shown) > 12) "M2" else "M1", tickangle = 0),
          yaxis = list(tickprefix = "€ ", separatethousands = TRUE),
          legend = list(orientation = "h", x = 0, y = 1.17),
          margin = list(t = 50, r = 20, b = 48))
      finance_modern_plot(p, date_axis = FALSE)
    })
    output$saldo_plot <- plotly::renderPlotly({
      s <- selection(); if (is.null(s)) return(empty_plot("Geen saldohistorie"))
      shown <- finance_dashboard_months(tail(s$current, 1), max(6L, s$n))
      df <- saldo_monthly() %>% dplyr::filter(.data$Maand %in% shown, is.finite(.data$Saldo))
      if (nrow(df) < 2L) return(empty_plot("Onvoldoende saldostanden voor een betrouwbare grafiek"))
      p <- plotly::plot_ly(df, x = ~Maand, y = ~Saldo, type = "scatter", mode = "lines+markers",
        name = "Totaal ING + ABN", line = list(color = "#087C68", shape = "spline", smoothing = .6, width = 1.8),
        marker = list(color = "#087C68", size = 5),
        hovertemplate = "%{x|%b %Y}<br>Banksaldo: € %{y:,.2f}<extra></extra>") %>%
        plotly::layout(xaxis = list(type = "date", tickformat = "%b %Y", dtick = if (length(shown) > 12) "M2" else "M1"),
          yaxis = list(tickprefix = "€ ", separatethousands = TRUE),
          margin = list(t = 18, r = 20, b = 45), showlegend = FALSE)
      finance_modern_plot(p, date_axis = FALSE)
    })
    output$saldo_note <- shiny::renderUI({
      gr <- saldo_growth(); a <- unname(gr["now"]); b <- unname(gr["previous"])
      shiny::div(class = "dashboard-note",
        "Saldoontwikkeling geselecteerde periode: ", shiny::strong(finance_dashboard_money(a, signed = TRUE)),
        " · vorige periode: ", finance_dashboard_money(b, signed = TRUE),
        shiny::span(class = "dashboard-note__small", " · Peildatum per rekening: laatste bekende transactie; Bigbank niet inbegrepen."))
    })
    output$insights <- shiny::renderUI({
      s <- selection()
      if (is.null(s)) return(shiny::div(class = "dashboard-empty", "Nog geen gegevens voor financiële signalen."))
      insights <- list()
      add <- function(title, text, kind = "neutral") {
        insights[[length(insights) + 1L]] <<- list(title = title, text = text, kind = kind)
      }
      # 1. Grootste structurele categorieverandering, laatste 3 vs vorige 3 volledige maanden.
      six <- finance_dashboard_months(ref_month(), 6)
      tx <- categorized() %>%
        dplyr::filter(.data$Maand %in% six, .data$`Af Bij` == "Af",
          !is.na(.data$Category), !as.character(.data$Category) %in% c("Overboeking (eigen)", "Sparen/Beleggen", "Onbekend", ""))
      if (nrow(tx) && length(six) == 6L) {
        bycat <- tx %>% dplyr::mutate(Part = ifelse(.data$Maand %in% six[1:3], "vorig", "recent")) %>%
          dplyr::group_by(.data$Category, .data$Part) %>%
          dplyr::summarise(Amount = sum(.data$`Bedrag (EUR)`, na.rm = TRUE) / 3, .groups = "drop")
        recent <- bycat %>% dplyr::filter(.data$Part == "recent") %>%
          dplyr::transmute(Category = .data$Category, recent = .data$Amount)
        previous <- bycat %>% dplyr::filter(.data$Part == "vorig") %>%
          dplyr::transmute(Category = .data$Category, vorig = .data$Amount)
        bycat <- dplyr::full_join(recent, previous, by = "Category") %>%
          dplyr::mutate(recent = dplyr::coalesce(.data$recent, 0),
                        vorig = dplyr::coalesce(.data$vorig, 0),
                        Delta = .data$recent - .data$vorig) %>%
          dplyr::filter(.data$Delta >= 40, .data$vorig >= 50, .data$Delta / .data$vorig >= .15) %>%
          dplyr::arrange(dplyr::desc(.data$Delta))
        if (nrow(bycat)) {
          x <- bycat[1, ]
          add(paste0("Meer uitgaven aan ", x$Category),
            paste0("Gemiddeld ", finance_dashboard_money(x$Delta), " per maand meer dan in de vorige drie maanden."), "warning")
        }
      }
      # 2. Spaarquote over de gekozen periode vs de vergelijkbare voorafgaande periode.
      a <- unname(s$now["Spaarquote"]); b <- unname(s$before["Spaarquote"])
      if (is.finite(a) && is.finite(b) && abs(a - b) >= 2) {
        add(if (a > b) "Je spaarquote verbetert" else "Je spaarquote daalt",
          paste0(finance_dashboard_change(a, b, "points"), " ten opzichte van de vorige periode."),
          if (a > b) "success" else "warning")
      }
      # 3. Totale uitgaven ten opzichte van vorige periode.
      ea <- unname(s$now["Uitgaven"]); eb <- unname(s$before["Uitgaven"])
      if (is.finite(ea) && is.finite(eb) && eb > 0 && abs(ea / eb - 1) >= .10) {
        add(if (ea > eb) "De totale uitgaven zijn gestegen" else "De totale uitgaven zijn gedaald",
          paste0(finance_dashboard_change(ea, eb, "percent"), " ten opzichte van de vorige periode."),
          if (ea > eb) "warning" else "success")
      }
      # 4. Saldogroei van de gekozen periode versus dezelfde voorafgaande periode.
      g <- saldo_growth(); a <- unname(g["now"]); b <- unname(g["previous"])
      if (is.finite(a) && is.finite(b) && abs(a - b) >= 500) {
        add(if (a > b) "Banksaldogroei versnelt" else "Banksaldogroei vertraagt",
          paste0("De saldoverandering is ", finance_dashboard_money(abs(a - b)),
                 if (a > b) " hoger" else " lager", " dan in de vorige periode."),
          if (a > b) "success" else "neutral")
      }
      if (!length(insights)) return(shiny::div(class = "dashboard-empty",
        "Geen opvallende afwijkingen boven de ingestelde drempels. Dat is ook nuttige informatie."))
      shiny::div(class = "dashboard-insight-list", lapply(head(insights, 4), function(x)
        shiny::div(class = paste("dashboard-insight", paste0("dashboard-insight--", x$kind)),
          shiny::span(class = "dashboard-insight__dot"),
          shiny::div(shiny::strong(x$title), shiny::p(x$text)))))
    })
  })
}

