mod_hypotheek_server <- function(id, hypotheek_cfg) {
  moduleServer(id, function(input, output, session) {

    # ---- Helper: annuïteitenberekening ---------------------------------------
    annuity_payment <- function(principal, annual_rate, months) {
      if (is.na(principal) || is.na(annual_rate) || is.na(months) || months <= 0) {
        return(NA_real_)
      }

      monthly_rate <- annual_rate / 12

      if (monthly_rate == 0) {
        return(principal / months)
      }

      principal * monthly_rate / (1 - (1 + monthly_rate)^(-months))
    }

    # ---- Huidige hypotheekdelen uit screenshot -------------------------------
    loan_parts <- purrr::map_dfr(
      hypotheek_cfg$loan_parts,
      tibble::as_tibble
    ) |>
      dplyr::transmute(
        Leningdeel = as.character(leningdeel),
        Product = product,
        Hoofdsom = as.numeric(hoofdsom),
        Rente = as.numeric(rente),
        Rentevast_tot = rentevast_tot,
        Bruto_maand = as.numeric(bruto_maand)
      )

    output$loan_parts <- finance_renderDT({
      loan_parts |>
        dplyr::mutate(
          Hoofdsom = scales::dollar(Hoofdsom, prefix = "€ ", big.mark = ".", decimal.mark = ","),
          Rente = paste0(format(Rente, decimal.mark = ",", nsmall = 2), "%"),
          Bruto_maand = scales::dollar(Bruto_maand, prefix = "€ ", big.mark = ".", decimal.mark = ",")
        ) |>
        DT::datatable(
          rownames = FALSE,
          options = list(pageLength = 5, dom = "t")
        )
    })

    # ---- Jaaroverzicht uit PDF ------------------------------------------------
    mortgage_years <- purrr::map_dfr(
      hypotheek_cfg$mortgage_years,
      tibble::as_tibble
    ) |>
      dplyr::transmute(
        Jaar = as.integer(jaar),
        Bruto_schuld = as.numeric(bruto_schuld),
        Aflossing = as.numeric(aflossing),
        Bruto_per_maand = as.numeric(bruto_per_maand),
        Netto_per_maand = as.numeric(netto_per_maand)
      )

    output$year_table <- finance_renderDT({
      mortgage_years |>
        dplyr::mutate(
          Bruto_schuld = scales::dollar(Bruto_schuld, prefix = "€ ", big.mark = ".", decimal.mark = ","),
          Aflossing = scales::dollar(Aflossing, prefix = "€ ", big.mark = ".", decimal.mark = ","),
          Bruto_per_maand = scales::dollar(Bruto_per_maand, prefix = "€ ", big.mark = ".", decimal.mark = ","),
          Netto_per_maand = scales::dollar(Netto_per_maand, prefix = "€ ", big.mark = ".", decimal.mark = ",")
        ) |>
        DT::datatable(
          rownames = FALSE,
          options = list(pageLength = 10, autoWidth = FALSE, scrollX = TRUE)
        )
    })

    # ---- Scenario-berekening --------------------------------------------------
    scenario <- reactive({
      months <- input$remaining_years * 12

      huidige_annuity_month <- loan_parts |>
        dplyr::filter(Leningdeel == "125") |>
        dplyr::pull(Bruto_maand)

      huidige_io_month <- loan_parts |>
        dplyr::filter(Leningdeel %in% c("129", "130")) |>
        dplyr::summarise(total = sum(Bruto_maand)) |>
        dplyr::pull(total)

      huidige_total_month <- huidige_annuity_month + huidige_io_month

      # Vanaf 2030: aflossingsvrij óf omzetten naar annuïteit.
      # Bij annuïteit wordt gerekend vanaf 2030 t/m het gekozen eindjaar.
      io_interest_month_2030 <- input$io_principal * (input$io_rate / 100) / 12

      io_annuity_month_2030 <- annuity_payment(
        principal = input$io_principal,
        annual_rate = input$io_rate / 100,
        months = max(1, (input$io_end_year - 2030) * 12)
      )

      io_month_2030 <- if (identical(input$io_strategy, "annuity")) {
        io_annuity_month_2030
      } else {
        io_interest_month_2030
      }

      io_strategy_label <- if (identical(input$io_strategy, "annuity")) {
        "Aflossingsvrij omgezet naar annuïteit"
      } else {
        "Aflossingsvrij gehouden"
      }

      total_month_2030 <- huidige_annuity_month + io_month_2030

      # Vanaf 2034: ook annuïteit krijgt nieuwe rente.
      annuity_month_2034 <- annuity_payment(
        principal = input$annuity_principal,
        annual_rate = input$annuity_rate / 100,
        months = months
      )

      total_month_2034 <- annuity_month_2034 + io_month_2030

      tibble::tibble(
        huidige_annuity_month = huidige_annuity_month,
        huidige_io_month = huidige_io_month,
        huidige_total_month = huidige_total_month,
        io_strategy = input$io_strategy,
        io_strategy_label = io_strategy_label,
        io_interest_month_2030 = io_interest_month_2030,
        io_annuity_month_2030 = io_annuity_month_2030,
        io_month_2030 = io_month_2030,
        io_end_year = input$io_end_year,
        total_month_2030 = total_month_2030,
        annuity_month_2034 = annuity_month_2034,
        total_month_2034 = total_month_2034,
        verschil_2030 = total_month_2030 - huidige_total_month,
        verschil_2034 = total_month_2034 - huidige_total_month
      )
    })

    output$scenario_summary <- renderUI({
      s <- scenario()

      fmt_eur <- function(x) {
        scales::dollar(
          x,
          prefix = "€ ",
          big.mark = ".",
          decimal.mark = ",",
          accuracy = 1
        )
      }

      tagList(
        fluidRow(
          column(
            4,
            div(
              class = "scenario-step-card",
              div(class = "scenario-step-year", "Nu"),
              div(class = "scenario-step-title", "Huidige bruto maandlast"),
              div(class = "scenario-step-value", fmt_eur(s$huidige_total_month)),
              div(
                class = "scenario-step-detail",
                paste0(
                  "Annuïteit: ", fmt_eur(s$huidige_annuity_month),
                  " · Aflossingsvrij: ", fmt_eur(s$huidige_io_month)
                )
              )
            )
          ),
          column(
            4,
            div(
              class = "scenario-step-card",
              div(class = "scenario-step-year", "Vanaf 2030"),
              div(class = "scenario-step-title", s$io_strategy_label),
              div(class = "scenario-step-value", fmt_eur(s$total_month_2030)),
              div(
                class = "scenario-step-detail",
                paste0(
                  "Maandlast deel 129+130: ", fmt_eur(s$io_month_2030),
                  if (identical(s$io_strategy, "annuity")) paste0(" · Eindjaar: ", s$io_end_year) else "",
                  " · Verschil: ", fmt_eur(s$verschil_2030)
                )
              )
            )
          ),
          column(
            4,
            div(
              class = "scenario-step-card scenario-step-highlight",
              div(class = "scenario-step-year", "Vanaf 2034"),
              div(class = "scenario-step-title", "Ook annuïteit tegen nieuwe rente"),
              div(class = "scenario-step-value", fmt_eur(s$total_month_2034)),
              div(
                class = "scenario-step-detail",
                paste0(
                  "Bestaande annuïteit: ", fmt_eur(s$annuity_month_2034),
                  " · Deel 129+130: ", fmt_eur(s$io_month_2030),
                  " · Verschil: ", fmt_eur(s$verschil_2034)
                )
              )
            )
          )
        )
      )
    })

    # ---- Scenario grafiek: maandlast nu, 2030 en 2034 ----------------------------
    output$rate_sandbox_plot <- plotly::renderPlotly({
      finance_modern_plot(local({
      s <- scenario()

      fmt_eur <- function(x) {
        scales::dollar(
          x,
          prefix = "€ ",
          big.mark = ".",
          decimal.mark = ",",
          accuracy = 1
        )
      }

      df <- tibble::tibble(
        Moment = factor(
          c("Nu", "Vanaf 2030", "Vanaf 2034"),
          levels = c("Nu", "Vanaf 2030", "Vanaf 2034")
        ),
        Maandlast = c(
          s$huidige_total_month,
          s$total_month_2030,
          s$total_month_2034
        ),
        Annuiteit = c(
          s$huidige_annuity_month,
          s$huidige_annuity_month,
          s$annuity_month_2034
        ),
        Aflossingsvrij = c(
          s$huidige_io_month,
          s$io_month_2030,
          s$io_month_2030
        ),
        Verschil = c(
          0,
          s$verschil_2030,
          s$verschil_2034
        ),
        Toelichting = c(
          "Huidige situatie",
          s$io_strategy_label,
          paste0(s$io_strategy_label, " + bestaande annuïteit opnieuw geprijsd")
        )
      )

      plotly::plot_ly(
        df,
        x = ~Moment,
        y = ~Maandlast,
        type = "bar",
        text = ~fmt_eur(Maandlast),
        textposition = "inside",
        insidetextanchor = "middle",
        textangle = 0,
        hovertext = ~paste0(
          Toelichting,
          "<br><br>",
          "Totale bruto maandlast: ", fmt_eur(Maandlast),
          "<br>",
          "Annuïteit: ", fmt_eur(Annuiteit),
          "<br>",
          "Aflossingsvrij: ", fmt_eur(Aflossingsvrij),
          "<br>",
          "Verschil met nu: ", fmt_eur(Verschil)
        ),
        hoverinfo = "text"
      ) |>
        plotly::layout(
          title = "Bruto maandlast in stappen: nu, 2030 en 2034",
          xaxis = list(title = ""),
          yaxis = list(title = "Bruto maandlast per maand"),
          showlegend = FALSE
        )

      }), date_axis = FALSE)
    })

    # ---- Grafiek: schuld en aflossing ----------------------------------------
    output$debt_plot <- plotly::renderPlotly({
      finance_modern_plot(local({
      plotly::plot_ly(mortgage_years, x = ~Jaar) |>
        plotly::add_bars(
          y = ~Aflossing,
          name = "Aflossing per jaar",
          yaxis = "y2",
          text = ~paste0(
            "Aflossing: ",
            scales::dollar(Aflossing, prefix = "€ ", big.mark = ".", decimal.mark = ",")
          ),
          hoverinfo = "text",
          opacity = 0.55
        ) |>
        plotly::add_lines(
          y = ~Bruto_schuld,
          name = "Bruto schuld",
          text = ~paste0(
            "Schuld: ",
            scales::dollar(Bruto_schuld, prefix = "€ ", big.mark = ".", decimal.mark = ",")
          ),
          hoverinfo = "text",
          line = list(width = 1.6, shape = "spline", smoothing = 0.7)
        ) |>
        plotly::layout(
          title = "Restschuld en jaarlijkse aflossing",
          xaxis = list(title = "Jaar"),
          yaxis = list(title = "Bruto schuld"),
          yaxis2 = list(
            title = "Aflossing",
            overlaying = "y",
            side = "right"
          ),
          barmode = "overlay"
        )

      }), date_axis = FALSE)
    })
  })
}

