# Server ----------------------------------------------------------------------
#' @param id            module-id
#' @param data_ing_all  onbewerkte (ongeselecteerde) ING-transacties (reactive/tibble of plain df)
#' @param data_ing_tbl  gefilterde ING-transacties voor de tabel (reactive)
#' @param colors        named kleurmapping (tags/personen)
#' @param initial_months list(default = ..., ing_cum = ...)
mod_ing_server <- function(id, data_ing_all, data_ing_tbl, colors, initial_months) {
  moduleServer(id, function(input, output, session) {

    # ------------ Config / events / filters ----------------------------------
    events_ing  <- cfg_events_to_df(cfg_get("events", "ing", default = list()))
    exclude_ing <- cfg_get("filters", "exclude_ing", default = character(0))

    # ------------ Gedeelde periode en KPI's per rekeninghouder -------------
    ing_range <- shiny::reactive({
      finance_kpi_period_range(data_ing_all()$Datum, input$kpi_period %||% "12")
    })

    # Een Tag vertegenwoordigt hier een rekeninghouder (zoals in de ING-grafieken).
    # Saldi worden eerst per bankrekening bepaald en daarna per Tag opgeteld.
    ing_owner_stats <- shiny::reactive({
      raw <- data_ing_all()
      rng <- ing_range()
      if (is.null(raw) || !nrow(raw) || is.null(rng)) return(NULL)

      df <- raw %>%
        dplyr::mutate(
          .volgorde = dplyr::row_number(),
          .tag = trimws(as.character(.data$Tag)),
          .rekening = trimws(as.character(.data$Rekening))
        ) %>%
        dplyr::filter(!is.na(.data$.tag), nzchar(.data$.tag))
      if (!nrow(df)) return(NULL)
      # Als bij enkele regels het rekeningnummer ontbreekt, gebruik de Tag
      # als fallback. Dit voorkomt het samenvoegen van onbekende rekeningen.
      df$.rekening[is.na(df$.rekening) | !nzchar(df$.rekening)] <-
        paste0("Tag: ", df$.tag[is.na(df$.rekening) | !nzchar(df$.rekening)])

      latest <- df %>%
        dplyr::filter(!is.na(.data$Datum), is.finite(.data$`Saldo na mutatie`)) %>%
        dplyr::arrange(.data$Datum, .data$.volgorde) %>%
        dplyr::group_by(.data$.tag, .data$.rekening) %>%
        dplyr::slice_tail(n = 1L) %>%
        dplyr::ungroup() %>%
        dplyr::group_by(.data$.tag) %>%
        dplyr::summarise(
          saldo = sum(.data$`Saldo na mutatie`),
          peildatum = max(.data$Datum),
          .groups = "drop"
        )

      in_range <- df %>%
        dplyr::filter(!is.na(.data$Datum),
                      .data$Datum >= rng$start, .data$Datum <= rng$end)
      previous_range <- NULL
      if (identical(input$kpi_period, "1")) {
        previous_start <- seq.Date(from = rng$start, by = "-1 month", length.out = 2L)[2L]
        previous_range <- df %>% dplyr::filter(
          !is.na(.data$Datum), .data$Datum >= previous_start, .data$Datum < rng$start)
      }
      complete <- finance_kpi_full_months(rng)
      if (length(complete)) {
        full_end <- as.Date(lubridate::ceiling_date(max(complete), "month") - lubridate::days(1))
      }
      persons <- unique(df$.tag)
      stats <- lapply(persons, function(person) {
        p <- in_range[in_range$.tag == person, , drop = FALSE]
        last <- latest[latest$.tag == person, , drop = FALSE]
        data.frame(
          tag = person,
          saldo = if (nrow(last)) last$saldo[1] else NA_real_,
          peildatum = if (nrow(last)) as.Date(last$peildatum[1]) else as.Date(NA),
          delta = sum(p$Bedrag_signed, na.rm = TRUE),
          vorige_mutatie = if (!is.null(previous_range)) {
            p_prev <- previous_range[previous_range$.tag == person, , drop = FALSE]
            if (nrow(p_prev)) sum(p_prev$Bedrag_signed, na.rm = TRUE) else NA_real_
          } else NA_real_,
          gemiddeld = if (length(complete)) {
            sum(p$Bedrag_signed[p$Datum <= full_end], na.rm = TRUE) / length(complete)
          } else NA_real_,
          maanden = length(complete)
        )
      })
      result <- dplyr::bind_rows(stats)
      # Plaats de rekeninghouders in dezelfde volgorde als de ING-legenda/config.
      config_order <- names(colors)
      result <- result[order(match(result$tag, config_order), result$tag, na.last = TRUE), , drop = FALSE]
      result
    })

    # De keuzes komen rechtstreeks uit de beschikbare ING-Tags; de ingestelde
    # keuze blijft behouden als de brondata na een import wordt ververst.
    shiny::observeEvent(ing_owner_stats(), {
      stats <- ing_owner_stats()
      tags <- if (!is.null(stats) && nrow(stats)) as.character(stats$tag) else character()
      choices <- c("Totaal ING" = "__total__", stats::setNames(tags, tags))
      current <- shiny::isolate(input$kpi_owner)
      selected <- if (!is.null(current) && current %in% unname(choices)) current else "__total__"
      shiny::updateSelectInput(session, "kpi_owner", choices = choices, selected = selected)
    }, ignoreInit = FALSE)

    output$kpi_groups <- shiny::renderUI({
      stats <- ing_owner_stats()
      rng <- ing_range()
      if (is.null(stats) || !nrow(stats) || is.null(rng)) {
        return(shiny::div(class = "text-muted mb-4", "Geen ING-gegevens beschikbaar."))
      }

      make_cards <- function(saldo, date, delta, avg, months, previous_delta) {
        shiny::fluidRow(class = "g-3 mb-3",
          shiny::column(4, finance_kpi_card(
            "Huidig saldo", finance_kpi_money(saldo),
            if (is.na(date)) "Geen saldodata" else paste0("Peildatum ", format(date, "%d-%m-%Y")),
            "wallet")),
          shiny::column(4, finance_kpi_card(
            if (identical(input$kpi_period, "1")) "Verschil met vorige maand" else "Gem. netto maandmutatie",
            finance_kpi_money(if (identical(input$kpi_period, "1")) {
              if (is.finite(avg) && is.finite(previous_delta)) avg - previous_delta else NA_real_
            } else avg, signed = TRUE),
            if (identical(input$kpi_period, "1")) {
              if (is.finite(previous_delta)) paste0("Vorige maand: ", finance_kpi_money(previous_delta, signed = TRUE))
              else "Vorige maand: onvoldoende gegevens"
            } else if (!months) "Geen volledige maanden" else paste0("Over ", months, " volledige maanden"),
            "exchange-alt",
            if (identical(input$kpi_period, "1")) {
              if (is.finite(avg) && is.finite(previous_delta)) avg - previous_delta >= 0 else NULL
            } else if (is.finite(avg)) avg >= 0 else NULL)),
          shiny::column(4, finance_kpi_card(
            "Saldoontwikkeling", finance_kpi_money(delta, signed = TRUE),
            if (identical(input$kpi_period, "1")) finance_kpi_month_comparison(delta, previous_delta)
            else paste0(format(rng$start, "%m-%Y"), " t/m ", format(rng$end, "%m-%Y")),
            "chart-line", if (is.finite(delta)) delta >= 0 else NULL))
        )
      }

      selected <- input$kpi_owner %||% "__total__"
      if (identical(selected, "__total__") || !(selected %in% stats$tag)) {
        # Het totaal telt de waarden van alle rekeninghouders op.
        saldo <- if (all(is.finite(stats$saldo))) sum(stats$saldo) else NA_real_
        peildatum <- if (all(!is.na(stats$peildatum))) min(stats$peildatum) else as.Date(NA)
        avg <- if (all(is.finite(stats$gemiddeld))) sum(stats$gemiddeld) else NA_real_
        delta <- sum(stats$delta)
        previous_delta <- if (all(is.finite(stats$vorige_mutatie))) sum(stats$vorige_mutatie) else NA_real_
        maanden <- stats$maanden[1]
        naam <- "Totaal ING · alle rekeninghouders"
      } else {
        s <- stats[match(selected, stats$tag), , drop = FALSE]
        saldo <- s$saldo[1]
        peildatum <- s$peildatum[1]
        delta <- s$delta[1]
        previous_delta <- s$vorige_mutatie[1]
        avg <- s$gemiddeld[1]
        maanden <- s$maanden[1]
        naam <- paste0("Rekeninghouder · ", selected)
      }
      shiny::tagList(
        shiny::div(class = "finance-chart-subtitle mb-2", naam),
        make_cards(saldo, peildatum, delta, avg, maanden, previous_delta)
      )
    })

    # ------------ Samenvattingen (brondata) ----------------------------------
    monthly_last_ing <- shiny::reactive(make_monthly_last_saldo(data_ing_all()))
    sums_ing         <- shiny::reactive(make_monthly_summaries(data_ing_all(), exclude_months = exclude_ing))

    # Iets duidelijkere 0-eurolijn, uitsluitend voor de bij-/afschrijvingen.
    # Plotly tekent deze op y = 0, zonder een extra trace of legenda-item.
    finance_mutation_zeroline <- function(p) {
      p$x$layout$yaxis <- utils::modifyList(
        if (is.list(p$x$layout$yaxis)) p$x$layout$yaxis else list(),
        list(zeroline = TRUE, zerolinecolor = "#9BAAA6", zerolinewidth = 1.6)
      )
      p
    }

    # ------------ Plot A: Mutaties per maand ---------------------------------
    output$trend <- renderPlotly({
      if (!is.list(sums_ing()) || !nrow(sums_ing()$monthly %||% tibble::tibble())) {
        return(empty_plot("Geen ING-transacties gevonden"))
      }

      build_monthly_plot(
        monthly_summary = sums_ing()$monthly,
        means_df        = sums_ing()$means[0, , drop = FALSE], # geen gemiddelde referentielijnen voor ING
        events          = events_ing,
        initial_months  = initial_months$default,
        y_range         = c(-5000, 5000),
        color_map       = colors
      ) %>%
        finance_modern_plot(date_axis = TRUE) %>%
        finance_kpi_limit_plot(ing_range()) %>%
        finance_mutation_zeroline()
    })

    # ------------ Plot B: Cumulatief -----------------------------------------
    output$cum <- renderPlotly({
      if (!nrow(monthly_last_ing())) {
        return(empty_plot("Geen data om cumulatief te tonen"))
      }
      build_cumulative_plot(
        monthly_last      = monthly_last_ing(),
        events            = events_ing,
        initial_months    = initial_months$ing_cum,
        show_point_labels = FALSE,
        color_map         = colors
      ) %>%
        finance_modern_plot(date_axis = TRUE) %>%
        finance_kpi_limit_plot(ing_range())
    })

    # ------------ Tabel: gefilterde data -------------------------------------
    finance_list_server(input, output, "bank_list",
      shiny::reactive(finance_bank_list_data(data_ing_tbl())), finance_bank_card)

    output$table <- finance_renderDT({
      df <- data_ing_tbl()
      if (is.null(df) || !nrow(df)) return(render_tx_table(df))
      df <- dplyr::select(df, -dplyr::any_of(c("Bedrag_signed", "Maand")))
      render_tx_table(df)
    })
  })
}

