# Server ----------------------------------------------------------------------
#' @param id              module-id
#' @param data_ing_all    alle (onbewerkte) ING-transacties
#' @param data_abn_all    alle (onbewerkte) ABN-transacties
#' @param color_total     hexkleur voor totale lijn
#' @param initial_months  initiële weergaveperiode
mod_total_server <- function(id, data_ing_all, data_abn_all, color_total, initial_months) {
  moduleServer(id, function(input, output, session) {

    # ------------ Gecombineerde kapitaalopbouw --------------------------------
    monthly_last_ing <- shiny::reactive(make_monthly_last_saldo(data_ing_all()))
    monthly_last_abn <- shiny::reactive(make_monthly_last_saldo(data_abn_all()))

    total_monthly_last <- shiny::reactive({ dplyr::bind_rows(
      monthly_last_ing() %>% dplyr::select(Maand, Saldo),
      monthly_last_abn() %>% dplyr::select(Maand, Saldo)
    ) %>%
      dplyr::group_by(Maand) %>%
      dplyr::summarise(Saldo = sum(Saldo, na.rm = TRUE), .groups = "drop") %>%
      dplyr::mutate(
        Tag         = "Totaal",
        Maand_label = format(Maand, "%b %Y"),
        Saldo_label = paste0(
          "€ ", format(round(Saldo, 2), big.mark = ".", decimal.mark = ",", nsmall = 2)
        ),
        tooltip_txt = paste0("Maand: ", Maand_label, "<br>Totaal saldo: ", Saldo_label)
      ) %>%
      dplyr::select(Tag, Maand, Saldo, Maand_label, Saldo_label, tooltip_txt) %>%
      dplyr::arrange(Maand)
    })

    events_total <- cfg_events_to_df(cfg_get("events", "total", default = list()))

    # ------------ KPI's uit dezelfde maandreeks als de grafiek ---------------
    total_range <- shiny::reactive({
      finance_kpi_period_range(total_monthly_last()$Maand, input$kpi_period %||% "12")
    })
    total_period_series <- shiny::reactive({
      rng <- total_range()
      df <- total_monthly_last()
      if (is.null(rng) || !nrow(df)) return(df[0, ])
      df %>% dplyr::filter(.data$Maand >= rng$start, .data$Maand <= rng$last_month) %>%
        dplyr::arrange(.data$Maand)
    })
    output$kpi_saldo <- shiny::renderUI({
      df <- total_monthly_last()
      if (!nrow(df)) return(finance_kpi_card("Laatste totaal banksaldo", "—", "Geen saldodata", "wallet"))
      row <- df[nrow(df), ]
      finance_kpi_card("Laatste totaal banksaldo", finance_kpi_money(row$Saldo),
                       paste0("ING + ABN · ", format(row$Maand, "%m-%Y")), "wallet")
    })
    output$kpi_ontwikkeling <- shiny::renderUI({
      df <- total_period_series()
      if (!nrow(df)) return(finance_kpi_card("Saldoontwikkeling", "—", "Geen gegevens", "chart-line"))
      if (identical(input$kpi_period, "1")) {
        cmp <- finance_kpi_saldo_month_comparison(total_monthly_last(), total_range())
        delta <- cmp$current
        subtitle <- finance_kpi_month_comparison(delta, cmp$previous)
      } else {
        # Voor langere perioden behouden we de bestaande eerste-tot-laatste-maandvergelijking.
        delta <- if (nrow(df) >= 2L) tail(df$Saldo, 1L) - df$Saldo[1L] else NA_real_
        subtitle <- if (nrow(df) < 2L) "Minimaal twee meetpunten nodig" else
          paste(format(df$Maand[1L], "%m-%Y"), "t/m", format(tail(df$Maand, 1L), "%m-%Y"))
      }
      finance_kpi_card("Saldoontwikkeling", finance_kpi_money(delta, signed = TRUE),
        subtitle,
        "chart-line", if (is.finite(delta)) delta >= 0 else NULL)
    })
    output$kpi_groei <- shiny::renderUI({
      df <- total_period_series()
      if (identical(input$kpi_period, "1")) {
        cmp <- finance_kpi_saldo_month_comparison(total_monthly_last(), total_range())
        v <- if (is.finite(cmp$current) && is.finite(cmp$previous)) cmp$current - cmp$previous else NA_real_
        return(finance_kpi_card("Verschil maandgroei",
          finance_kpi_money(v, signed = TRUE),
          if (is.finite(cmp$previous)) paste0("Vorige maandgroei: ", finance_kpi_money(cmp$previous, signed = TRUE))
          else "Vorige maand: onvoldoende gegevens",
          "chart-line", if (is.finite(v)) v >= 0 else NULL))
      }
      complete <- finance_kpi_full_months(total_range())
      # Alleen opeenvolgende, volledige maanden gebruiken. Ontbrekende data
      # worden niet als een maand zonder saldoverandering geïnterpreteerd.
      df <- df %>% dplyr::filter(.data$Maand %in% complete) %>% dplyr::arrange(.data$Maand)
      if (nrow(df) >= 2L) {
        gap <- as.integer(12L * (as.integer(format(df$Maand[-1L], "%Y")) -
                                  as.integer(format(head(df$Maand, -1L), "%Y"))) +
                           (as.integer(format(df$Maand[-1L], "%m")) -
                            as.integer(format(head(df$Maand, -1L), "%m"))))
        changes <- diff(df$Saldo)[gap == 1L]
      } else changes <- numeric()
      v <- if (length(changes)) mean(changes) else NA_real_
      finance_kpi_card("Gem. maandgroei banksaldo", finance_kpi_money(v, signed = TRUE),
        if (!length(changes)) "Geen opeenvolgende volledige maanden" else
          paste0("Gemiddelde over ", length(changes), " maandverschillen"),
        "chart-line", if (is.finite(v)) v >= 0 else NULL)
    })

    # ------------ Plot: cumulatieve opbouw -----------------------------------
    output$cum_total <- plotly::renderPlotly({
      if (!nrow(total_monthly_last())) {
        return(empty_plot("Geen data om te tonen"))
      }

      build_cumulative_plot(
        monthly_last      = total_monthly_last(),
        events            = events_total,
        initial_months    = initial_months,
        show_point_labels = FALSE,
        color_map         = c("Totaal" = color_total %||% "#1f77b4")
      ) %>%
        finance_modern_plot(date_axis = TRUE) %>%
        finance_kpi_limit_plot(total_range())
    })

    # ------------ KPI’s: actieve deposito’s ----------------------------------
    deposito_df        <- load_bigbank_df()
    active_deposits_df <- deposito_df %>%
      dplyr::filter(!is.na(status), tolower(trimws(as.character(status))) == "actief")

    row_layout_active <- list("Actief" = c(3))

    output$kpi_active_total <- renderUI({
      build_deposito_kpi_ui(
        df         = active_deposits_df,
        order_vec  = cfg_get("bigbank", "order", default = character(0)),
        row_layout = row_layout_active,
        columns    = 3
      )
    })
  })
}

finance_vl_prepare_uitgaven <- function(raw, p) {
  if (is.null(p) || !nrow(raw)) return(finance_vl_empty_uitgaven(raw))
  # We categoriseren de hele historie: eventuele herkenningshints behouden zo
  # voldoende transacties, terwijl we pas daarna op maanden filteren.
  recent <- dplyr::filter(raw, !is.na(.data$Datum),
                    .data$Datum >= p$start, .data$Datum < p$end)
  if (!nrow(recent)) return(finance_vl_empty_uitgaven(recent))
  all_out <- dplyr::filter(raw, !is.na(.data$Datum),
                      .data$`Af Bij` == "Af", is.finite(.data$`Bedrag (EUR)`))
  rec <- if (nrow(all_out)) detect_recurring(all_out) else NULL
  d <- finance_apply_corrections(categorize_transactions(
    recent, recurring_hint = rec,
    own_ibans = OWN_IBANS, salary_senders = SALARY_SENDERS
  ))
  # De ID wordt bepaald vóór selectie en filtering, zodat één betaling
  # afzonderlijk kan worden uitgesloten, ook bij dezelfde datum/tegenpartij.
  d$transactie_id <- finance_transaction_ids(d)
  d |>
    dplyr::filter(
      .data$`Af Bij` == "Af",
      is.finite(.data$`Bedrag (EUR)`),
      abs(.data$`Bedrag (EUR)`) > 0
    ) |>
    dplyr::mutate(
      Categorie = as.character(.data$Category),
      Categorie = dplyr::coalesce(
        dplyr::na_if(.data$Categorie, ""),
        "Onbekend"
      ),
      Groep = finance_vl_group(.data$Categorie),
      Uitgave = abs(.data$`Bedrag (EUR)`),
      Maand = as.Date(format(.data$Datum, "%Y-%m-01")),
      Tegenpartij = as.character(.data$`Naam / Omschrijving`)
    ) |>
    dplyr::filter(
      !.data$Categorie %in% c("Overboeking (eigen)", "Sparen/Beleggen")
    )
}

# ---- R/mod_vaste_lasten.R --------------------------------------------------
# Vaste lasten: categorie-gebaseerde analyse van zes afgesloten kalendermaanden.
# Geen contractregister: dit zijn waargenomen uitgaven, geen voorspelde facturen.

finance_vl_money <- function(x) {
  if (length(x) != 1L || is.na(x) || !is.finite(x)) return("—")
  paste0("€ ", format(round(x, 2), big.mark = ".", decimal.mark = ",",
                       nsmall = 2, trim = TRUE, scientific = FALSE))
}

finance_vl_group <- function(category) {
  fixed <- c("Wonen: Huur", "Wonen: Hypotheek", "Wonen: School", "Vaste lasten: Energie/Water",
             "Vaste lasten: Telecom/Internet", "Verzekeringen (overig)",
             "Zorg & Zorgverzekering", "Abonnementen", "Belastingen/Overheid")
  ifelse(as.character(category) %in% fixed, "Vaste verplichtingen", "Variabele uitgaven")
}

# Eindigt op de eerste dag van de maand van de laatst beschikbare boeking.
# Daardoor zijn de zes voorafgaande maanden volledig afgesloten (mits ingeladen).
finance_vl_window <- function(dates, months = 6L) {
  dates <- as.Date(dates)
  dates <- dates[!is.na(dates)]
  if (!length(dates)) return(NULL)
  end <- as.Date(format(max(dates), "%Y-%m-01"))
  start <- seq(end, by = "-1 month", length.out = months + 1L)[months + 1L]
  list(start = start, end = end, peildatum = max(dates), maanden = months)
}

