      "verkeerd ingedeelde betalingen de categorisering. Eigen overboekingen en sparen/beleggen tellen niet mee.")
  )
}

mod_vaste_lasten_server <- function(id, data_ing_all, data_abn_all, category_version = NULL) {
  shiny::moduleServer(id, function(input, output, session) {
    # De periode volgt de beschikbare gegevens; de globale Analyse-filter heeft
    # bewust geen invloed op deze vaste-lastenberekening.
    bron <- shiny::reactive({
      dplyr::bind_rows(
        dplyr::mutate(data_ing_all(), Bank = "ING"),
        dplyr::mutate(data_abn_all(), Bank = "ABN")
      )
    })
    # Zelfde rekeningkeuzes als Analyse & trends, inclusief houders uit YAML.
    # Alleen de labels bevatten namen; de filterwaarden blijven bank/rekening.
    shiny::observe({
      tx <- bron()
      keuzes <- c("Alle rekeningen" = "all",
                   "ING · alle rekeningen" = "bank:ING",
                   "ABN · alle rekeningen" = "bank:ABN")

      if (is.data.frame(tx) && nrow(tx) &&
          all(c("Bank", "Rekening") %in% names(tx))) {
        paren <- unique(data.frame(
          Bank = as.character(tx$Bank),
          Rekening = trimws(as.character(tx$Rekening)),
          stringsAsFactors = FALSE
        ))
        paren <- paren[!is.na(paren$Rekening) & nzchar(paren$Rekening) &
                         paren$Bank %in% c("ING", "ABN"), , drop = FALSE]
        paren <- paren[order(paren$Bank, paren$Rekening), , drop = FALSE]

        if (nrow(paren)) {
          rekeninghouders <- cfg_get("tags", "accounts", default = list())
          naam_per_rekening <- character()
          if (is.list(rekeninghouders) && length(rekeninghouders)) {
            sleutels <- names(rekeninghouders)
            if (!is.null(sleutels)) {
              normaliseer_rekening <- function(x) {
                toupper(gsub("[^A-Z0-9]", "", as.character(x)))
              }
              naam_per_rekening <- vapply(rekeninghouders, function(item) {
                waarde <- unlist(item, use.names = FALSE)
                if (!length(waarde) || is.na(waarde[1])) "" else trimws(as.character(waarde[1]))
              }, character(1))
              names(naam_per_rekening) <- normaliseer_rekening(sleutels)
            }
          }
          opties <- paste0("account:", paren$Bank, ":", paren$Rekening)
          labels <- paste(paren$Bank, paren$Rekening, sep = " · ")
          if (length(naam_per_rekening)) {
            rekening_sleutels <- toupper(gsub("[^A-Z0-9]", "", paren$Rekening))
            houders <- unname(naam_per_rekening[rekening_sleutels])
            bekend <- !is.na(houders) & nzchar(houders)
            labels[bekend] <- paste0(labels[bekend], " (", houders[bekend], ")")
          }
          names(opties) <- labels
          keuzes <- c(keuzes, opties)
        }
      }
      huidig <- shiny::isolate(input$rekening)
      if (is.null(huidig) || !huidig %in% unname(keuzes)) huidig <- "all"
      shiny::updateSelectInput(session, "rekening", choices = keuzes, selected = huidig)
    })

    bron_rekening <- shiny::reactive({
      tx <- bron()
      keuze <- input$rekening
      if (is.null(keuze) || identical(keuze, "all") || !nrow(tx)) return(tx)
      if (startsWith(keuze, "bank:")) {
        bank <- substring(keuze, 6L)
        return(dplyr::filter(tx, .data$Bank == bank))
      }
      if (startsWith(keuze, "account:")) {
        sleutel <- substring(keuze, 9L)
        return(dplyr::filter(tx,
          paste(.data$Bank, trimws(as.character(.data$Rekening)), sep = ":") == sleutel))
      }
      tx
    })

    # De referentieperiode blijft gelijk bij wisselen van rekening.
    periode <- shiny::reactive(finance_vl_window(bron()$Datum))

    exclusions_version <- shiny::reactiveVal(0L)
    excluded_ids <- shiny::reactive({
      exclusions_version()
      finance_vl_read_exclusions()
    })

    uitgaven <- shiny::reactive({
      if (is.function(category_version)) category_version()
      keuze <- input$rekening
      if (is.null(keuze) || !nzchar(keuze)) keuze <- "all"
      x <- FINANCE_SNAPSHOT$prepared$vaste_lasten[[keuze]]
      if (is.null(x)) x <- FINANCE_SNAPSHOT$prepared$vaste_lasten[["all"]]
      x
    })

    uitgaven_actief <- shiny::reactive({
      d <- uitgaven()
      if (!nrow(d)) return(d)
      d[!d$transactie_id %in% excluded_ids(), , drop = FALSE]
    })

    categorieen <- shiny::reactive({
      d <- uitgaven_actief()
      if (!nrow(d)) return(tibble::tibble(Categorie = character(), Groep = character(),
                                          Totaal = numeric(), Transacties = integer(),
                                          Gemiddeld = numeric()))
      d |>
        dplyr::group_by(.data$Categorie, .data$Groep) |>
        dplyr::summarise(Totaal = sum(.data$Uitgave), Transacties = dplyr::n(), .groups = "drop") |>
        dplyr::mutate(Gemiddeld = .data$Totaal / periode()$maanden) |>
        dplyr::arrange(dplyr::desc(.data$Gemiddeld))
    })

    maanden <- shiny::reactive({
      p <- periode()
      if (is.null(p)) return(tibble::tibble(Maand = as.Date(character()), Groep = character(), Uitgave = numeric()))
      months <- seq(p$start, by = "1 month", length.out = p$maanden)
      grid <- tidyr::expand_grid(Maand = months,
        Groep = c("Vaste verplichtingen", "Variabele uitgaven"))
      d <- uitgaven_actief()
      if (!nrow(d)) return(dplyr::mutate(grid, Uitgave = 0))
      x <- d |>
        dplyr::group_by(.data$Maand, .data$Groep) |>
        dplyr::summarise(Uitgave = sum(.data$Uitgave), .groups = "drop")
      dplyr::left_join(grid, x, by = c("Maand", "Groep")) |>
        dplyr::mutate(Uitgave = tidyr::replace_na(.data$Uitgave, 0))
    })

    output$periode_info <- shiny::renderUI({
      p <- periode()
      if (is.null(p)) return(shiny::span(class = "vl-muted", "Geen transacties beschikbaar"))
      shiny::span(class = "vl-muted", sprintf("Analyseperiode: %s t/m %s (6 afgesloten kalendermaanden). Laatste brontransactie: %s.",
        format(p$start, "%d-%m-%Y"), format(p$end - 1, "%d-%m-%Y"),
        format(p$peildatum, "%d-%m-%Y")))
    })
    output$vast_maand <- shiny::renderText(finance_vl_money(sum(categorieen()$Gemiddeld[categorieen()$Groep == "Vaste verplichtingen"])))
    output$variabel_maand <- shiny::renderText(finance_vl_money(sum(categorieen()$Gemiddeld[categorieen()$Groep == "Variabele uitgaven"])))
    output$totaal_maand <- shiny::renderText(finance_vl_money(sum(categorieen()$Gemiddeld)))
    output$jaar <- shiny::renderText(finance_vl_money(sum(categorieen()$Gemiddeld) * 12))

    # Reserveer voldoende verticale ruimte voor alle categorieën, ook mobiel.
    output$categorie_plot_ui <- shiny::renderUI({
      n <- nrow(categorieen())
      h <- sprintf("%dpx", max(390L, 115L + 44L * n))
      shiny::div(class = "vl-category-chart",
        style = paste0("--vl-category-height:", h, ";"),
        finance_mobile_plot(session$ns("categorie_plot"), height = h))
    })

    output$categorie_plot <- plotly::renderPlotly({
      d <- categorieen()
      if (!nrow(d)) return(empty_plot("Geen uitgaven in de analyseperiode"))
      d <- dplyr::arrange(d, .data$Gemiddeld)
      labels <- vapply(as.character(d$Categorie), function(x) {
        paste(strwrap(x, width = 19), collapse = "<br>")
      }, character(1), USE.NAMES = FALSE)
      plotly::plot_ly(d, x = ~Gemiddeld, y = ~factor(Categorie, levels = Categorie),
        color = ~Groep, colors = c("Vaste verplichtingen" = "#087C68", "Variabele uitgaven" = "#729F92"),
        type = "bar", orientation = "h",
        text = ~vapply(Gemiddeld, finance_vl_money, character(1)),
        textposition = "outside", textangle = 0,
        textfont = list(size = 10, color = "#64748B"),
        cliponaxis = FALSE,
        hovertemplate = "%{y}<br>€ %{x:,.2f} per maand<extra></extra>") |>
        plotly::layout(xaxis = list(title = "Gemiddeld per maand (€)",
          range = c(0, max(d$Gemiddeld, na.rm = TRUE) * 1.35)),
          yaxis = list(title = "", automargin = TRUE,
            type = "category", categoryorder = "array",
            categoryarray = as.character(d$Categorie),
            tickmode = "array", tickvals = as.character(d$Categorie),
            ticktext = labels, tickfont = list(size = 10)),
          margin = list(l = 20, r = 20, t = 65, b = 50),
          legend = list(orientation = "h", y = 1.02, yanchor = "bottom"))
    })
    output$maand_plot <- plotly::renderPlotly({
      d <- maanden()
      if (!nrow(d)) return(empty_plot("Geen maanden beschikbaar"))
      plotly::plot_ly(d, x = ~Maand, y = ~Uitgave, color = ~Groep,
        colors = c("Vaste verplichtingen" = "#087C68", "Variabele uitgaven" = "#729F92"),
        type = "bar", hovertemplate = "%{x|%b %Y}<br>€ %{y:,.2f}<extra></extra>") |>
        plotly::layout(barmode = "stack", xaxis = list(title = "", tickformat = "%b %Y"),
          yaxis = list(title = "Uitgaven (€)"), margin = list(t = 15, b = 45),
          legend = list(orientation = "h", y = 1.2))
    })

    get_categories <- shiny::reactive({
      d <- categorieen()
      if (identical(input$groep, "vast")) d <- dplyr::filter(d, .data$Groep == "Vaste verplichtingen")
      if (identical(input$groep, "variabel")) d <- dplyr::filter(d, .data$Groep == "Variabele uitgaven")
      d
    })
    finance_list_server(input, output, "category_list", get_categories, function(row) {
      total <- sum(get_categories()$Gemiddeld, na.rm = TRUE)
      finance_list_card(row$Categorie, row$Groep, paste0(finance_vl_money(row$Gemiddeld), " / mnd"),
        fields = list(finance_list_field("Totaal 6 maanden", finance_vl_money(row$Totaal)),
                      finance_list_field("Betalingen", row$Transacties)),
        action = finance_list_action(session, "card_category", row$Categorie, "Bekijk tegenpartijen"),
        selected = identical(as.character(row$Categorie), input$categorie),
        share = if (total > 0) row$Gemiddeld / total else 0)
    })
    shiny::observeEvent(input$card_category, {
      if (input$card_category %in% get_categories()$Categorie)
        shiny::updateSelectInput(session, "categorie", selected = input$card_category)
    })
    output$categorie_tabel <- finance_renderDT({
      d <- get_categories() |>
        dplyr::transmute(Categorie = .data$Categorie, Type = .data$Groep,
          `Per maand` = .data$Gemiddeld, `Over 6 maanden` = .data$Totaal,
          Betalingen = .data$Transacties)
      DT::datatable(d, rownames = FALSE, selection = "single", class = "stripe hover compact",
        options = list(pageLength = 10, scrollX = TRUE, dom = "ftip", language = list(search = "Zoeken:"))) |>
        DT::formatCurrency(c("Per maand", "Over 6 maanden"), currency = "€ ", mark = ".", dec = ",", digits = 2)
    })
    shiny::observe({
      # Ook categorieën waarvan alle transacties zijn uitgesloten blijven selecteerbaar.
      choices <- sort(unique(uitgaven()$Categorie))
      selected <- shiny::isolate(input$categorie)
      shiny::updateSelectInput(session, "categorie", choices = choices,
        selected = if (length(selected) && selected %in% choices) selected else head(choices, 1))
    })
    shiny::observeEvent(input$categorie_tabel_rows_selected, {
      d <- get_categories()
      i <- input$categorie_tabel_rows_selected
      if (length(i) == 1L && i > 0 && i <= nrow(d))
        shiny::updateSelectInput(session, "categorie", selected = d$Categorie[[i]])
    })
    details <- shiny::reactive({
      shiny::req(input$categorie)
      dplyr::filter(uitgaven(), .data$Categorie == input$categorie)
    })
    # Eén selectie voor de voorlaatste tabel. Zo kan een gebruiker rechtstreeks
    # van categorie -> tegenpartij -> individuele transacties doorklikken.
    tegenpartijen_data <- shiny::reactive({
      d <- details()
      if (nrow(d)) d <- d[!d$transactie_id %in% excluded_ids(), , drop = FALSE]
      d |>
        dplyr::group_by(.data$Tegenpartij) |>
        dplyr::summarise(Betalingen = dplyr::n(), `Totaal 6 maanden` = sum(.data$Uitgave),
          `Laatst betaald` = if (all(is.na(.data$Datum))) as.Date(NA) else max(.data$Datum, na.rm = TRUE),
          .groups = "drop") |>
        dplyr::mutate(`Per maand` = .data$`Totaal 6 maanden` / periode()$maanden) |>
        dplyr::arrange(dplyr::desc(.data$`Totaal 6 maanden`))
    })

    # Bij een andere categorie is de eerder aangeklikte tegenpartij niet meer
    # van toepassing. Een nieuwe klik selecteert opnieuw een betaalrelatie.
    geselecteerde_tegenpartij <- shiny::reactiveVal(NULL)
    shiny::observeEvent(input$categorie, {
      geselecteerde_tegenpartij(NULL)
    }, ignoreInit = TRUE)

    shiny::observeEvent(input$tegenpartijen_rows_selected, {
      i <- input$tegenpartijen_rows_selected
      d <- shiny::isolate(tegenpartijen_data())
      if (length(i) == 1L && i >= 1L && i <= nrow(d)) {
        geselecteerde_tegenpartij(d$Tegenpartij[[i]])
      } else {
        geselecteerde_tegenpartij(NULL)
      }
    })

    shiny::observeEvent(input$wis_tegenpartij, {
      geselecteerde_tegenpartij(NULL)
      DT::selectRows(DT::dataTableProxy("tegenpartijen", session = session), NULL)
    })

    finance_list_server(input, output, "party_list", tegenpartijen_data, function(row) {
      finance_list_card(row$Tegenpartij, paste(row$Betalingen, "betalingen"),
        paste0(finance_vl_money(row$`Per maand`), " / mnd"),
        fields = list(finance_list_field("Totaal 6 maanden", finance_vl_money(row$`Totaal 6 maanden`)),
                      finance_list_field("Laatst betaald", finance_list_date(row$`Laatst betaald`))),
        action = finance_list_action(session, "card_party", row$Tegenpartij, "Bekijk betalingen"),
        selected = identical(as.character(row$Tegenpartij), geselecteerde_tegenpartij()))
    })
    shiny::observeEvent(input$card_party, {
      if (input$card_party %in% tegenpartijen_data()$Tegenpartij)
        geselecteerde_tegenpartij(input$card_party)
    })
    output$tegenpartijen <- finance_renderDT({
      d <- tegenpartijen_data()
      selected <- match(geselecteerde_tegenpartij(), d$Tegenpartij)
      if (!length(selected) || is.na(selected)) selected <- NULL
      DT::datatable(d, rownames = FALSE, selection = list(mode = "single", selected = selected),
        class = "stripe hover compact",
        options = list(pageLength = 8, scrollX = TRUE, dom = "ftip",
          language = list(search = "Zoeken:", zeroRecords = "Geen tegenpartijen gevonden"))) |>
        DT::formatCurrency(c("Totaal 6 maanden", "Per maand"), currency = "€ ", mark = ".", dec = ",", digits = 2) |>
        DT::formatDate("Laatst betaald", method = "toLocaleDateString")
    }, server = FALSE)

    transacties_keuze <- shiny::reactive({
      if (identical(input$transactie_scope, "uitgesloten")) {
        d <- uitgaven()
        d <- d[d$transactie_id %in% excluded_ids(), , drop = FALSE]
      } else {
        d <- details()
        tp <- geselecteerde_tegenpartij()
        if (!is.null(tp)) d <- d[d$Tegenpartij == tp, , drop = FALSE]
      }
      dplyr::arrange(d, dplyr::desc(.data$Datum))
    })

    output$transactie_selectie_info <- shiny::renderUI({
      if (identical(input$transactie_scope, "uitgesloten")) {
        return(shiny::p(class = "vl-muted", "Alle eerder uitgesloten betalingen in de huidige analyseperiode."))
      }
      cat <- input$categorie
      tp <- geselecteerde_tegenpartij()
      label <- if (!is.null(tp)) paste0(cat, " / ", tp) else cat
      shiny::p(class = "vl-muted", paste0("Getoonde selectie: ", label,
        ". Kies een tegenpartij hierboven om de selectie te verfijnen."))
    })

    finance_list_server(input, output, "expense_list", transacties_keuze, function(row) {
      status <- if (row$transactie_id %in% excluded_ids()) "Uitgesloten" else "Meegenomen"
      finance_list_card(row$Tegenpartij,
        paste(finance_list_date(row$Datum), row$Bank, status, sep = " · "),
        paste0("− ", finance_vl_money(row$Uitgave)),
        fields = list(finance_list_field("Categorie", row$Categorie),
                      finance_list_field("Status", status),
                      finance_list_field("Rekening", finance_list_value(row, "Rekening", "—"))))
    })
    output$transacties <- finance_renderDT({
      d <- transacties_keuze()
      exclusions <- excluded_ids()
      display <- dplyr::transmute(d, Datum = .data$Datum, Bank = .data$Bank,
        Tegenpartij = .data$Tegenpartij, Bedrag = .data$Uitgave,
        Status = ifelse(.data$transactie_id %in% exclusions, "Uitgesloten", "Meegenomen"))
      DT::datatable(display, rownames = FALSE, selection = "none",
        class = "stripe hover compact",
        options = list(pageLength = 10, scrollX = TRUE, dom = "ftip",
          language = list(search = "Zoeken:", zeroRecords = "Geen transacties gevonden"))) |>
        DT::formatCurrency("Bedrag", currency = "€ ", mark = ".", dec = ",", digits = 2) |>
        DT::formatDate("Datum", method = "toLocaleDateString")
    }, server = FALSE)

    output$uitsluiting_info <- shiny::renderUI({
      n <- sum(uitgaven()$transactie_id %in% excluded_ids())
      shiny::p(class = "vl-muted", sprintf(
        "%d transactie(s) uitgesloten in de huidige analyseperiode. Alle KPI's, grafieken en categoriebedragen worden zonder deze betalingen berekend.", n))
    })

  })
}

# ---- R/utils_bigbank_ui.R ----

pluralize_looptijd <- function(n, deel) {
  deel <- tolower(deel %||% "maand")
  if (deel %in% c("maand", "maanden")) {
    paste0(n, " ", ifelse(is.na(n) || n == 1, "maand", "maanden"))
  } else {
    paste(n, deel)
  }
}

build_deposito_kpi_ui <- function(df, order_vec = NULL, row_layout = NULL, columns = 3) {
  if (nrow(df) == 0) return(div("Geen deposito's gevonden."))
  
  if (!is.null(order_vec)) {
    df$deposito_nr <- as.character(df$deposito_nr)
    ord <- match(df$deposito_nr, order_vec)
    df$.__ord <- ord
    df <- df[order(is.na(df$.__ord), df$.__ord, df$deposito_nr), , drop = FALSE]
    df$.__ord <- NULL
  }
  
  df$status <- factor(df$status, levels = c("Actief", "Uitbetaald"))
  sections <- split(df, df$status, drop = TRUE)
  
  make_card <- function(r) {
    inactive <- tolower(as.character(r$status)) == "uitbetaald"
    classes  <- if (inactive) "kpi-card kpi-card--inactive" else "kpi-card"
    
    tags$div(class = classes,
             tags$div(class = "kpi-card-inner",
                      tags$div(class = "kpi-card-header",
                               paste("Deposito nummer:", r$deposito_nr)),
                      tags$div(
                        tags$span(class = "kpi-amount", format_euro(r$depositobedrag, digits = 0)),
                        tags$span(class = "kpi-plus",   format_euro(r$totaalopgebouwde_rente, digits = 2)),
                        tags$span(class = "kpi-sub",    "Totaal opgebouwde rente")
                      ),
                      tags$div(class = "kpi-foot",
                               paste0(
                                 "Rentepercentage: ", format(r$rentepercentage, nsmall = 1), "%, ",
                                 "looptijd: ", pluralize_looptijd(r$looptijd, r$looptijddeel), " (", r$eigenaar, "), ",
                                 "activeringsdatum: ", format(r$activeringsdatum, "%d-%m-%Y"),
                                 " vervaldatum: ",     format(r$vervaldatum,     "%d-%m-%Y")
                               )
                      )
             ),
             if (inactive) tags$div(class = "kpi-overlay"),
             if (inactive) tags$div(class = "kpi-stamp", "UITBETAALD")
    )
  }
  
  make_placeholder <- function() tags$div(class = "kpi-card kpi-empty")
  
  ui_list <- list()
  for (nm in names(sections)) {
    block <- sections[[nm]]
    cards <- list()
    layout_vec <- if (!is.null(row_layout) && !is.null(row_layout[[nm]])) row_layout[[nm]] else integer(0)
    
    idx <- 1L
    if (length(layout_vec)) {
      for (r in layout_vec) {
        if (idx > nrow(block)) break
        take <- min(r, nrow(block) - idx + 1L)
        for (j in seq_len(take)) {
          cards[[length(cards)+1]] <- make_card(block[idx, ])
          idx <- idx + 1L
        }
        pad <- columns - take
        if (pad > 0) for (p in seq_len(pad)) cards[[length(cards)+1]] <- make_placeholder()
      }
    }
    
    if (idx <= nrow(block)) {
      remaining <- block[idx:nrow(block), , drop = FALSE]
      for (i in seq_len(nrow(remaining))) cards[[length(cards)+1]] <- make_card(remaining[i, ])
      rem_in_last_row <- nrow(remaining) %% columns
      if (rem_in_last_row > 0) {
        for (p in seq_len(columns - rem_in_last_row)) cards[[length(cards)+1]] <- make_placeholder()
      }
    }
    
    ui_list[[length(ui_list)+1]] <- tags$div(class = "kpi-section-title", toupper(nm))
    ui_list[[length(ui_list)+1]] <- tags$div(class = "kpi-grid", cards)
  }
  
  do.call(tagList, ui_list)
}

finance_normalize_counterparty <- function(x) {
  x <- as.character(x)
  x[is.na(x)] <- ""
  tolower(gsub("\\s+", " ", trimws(x), perl = TRUE))
}

finance_transaction_ids <- function(df) {
  if (!requireNamespace("digest", quietly = TRUE)) stop("Installeer digest: install.packages('digest')")
  if (!nrow(df)) return(character())
  cols <- c("Bank", "Rekening", "Datum", "Af Bij", "Bedrag (EUR)",
            "Saldo na mutatie", "Naam / Omschrijving", "Tegenrekening",
            "Mededelingen", "Mutatiesoort", "Code", "Tag")
  canon <- lapply(cols, function(x) {
    v <- if (x %in% names(df)) df[[x]] else rep(NA, nrow(df))
    if (inherits(v, "Date")) v <- format(v, "%Y-%m-%d")
    if (is.numeric(v)) v <- ifelse(is.na(v), "<NA>", sprintf("%.8f", v))
    v <- as.character(v)
    v[is.na(v)] <- "<NA>"
    enc2utf8(v)
  })
  fingerprints <- vapply(seq_len(nrow(df)), function(i) {
    x <- vapply(canon, `[[`, character(1), i)
    paste0(nchar(x, type = "bytes"), ":", x, collapse = "|")
  }, character(1))
  ordinal <- ave(seq_along(fingerprints), fingerprints, FUN = seq_along)
  vapply(seq_along(fingerprints), function(i)
    digest::digest(paste0(fingerprints[i], "#", ordinal[i]), algo = "sha256", serialize = FALSE), character(1))
}

finance_read_corrections <- function() finance_mobile_table("categorie_correcties")[, c("transactie_id", "categorie"), drop = FALSE]
finance_read_rules <- function() {
  x <- finance_mobile_table("categorie_regels")
  x[order(x$bank, x$tegenpartij_naam), c("id", "bank", "tegenpartij_sleutel", "tegenpartij_naam", "categorie", "vanaf_datum", "gewijzigd_op"), drop = FALSE]
}

# Match alleen op exacte (genormaliseerde) tegenpartijnaam BINNEN dezelfde bank.
# Bestaande handmatige correcties krijgen ALTIJD voorrang op een herkenningsregel.
finance_rule_matches <- function(df, rules = finance_read_rules()) {
  result <- rep(NA_integer_, nrow(df))
  if (!nrow(df) || !nrow(rules)) return(result)
  bank <- as.character(df$Bank)
  key <- finance_normalize_counterparty(df$`Naam / Omschrijving`)
  lookup <- paste(rules$bank, rules$tegenpartij_sleutel, sep = "\r")
  result <- match(paste(bank, key, sep = "\r"), lookup)
  if ("Datum" %in% names(df)) {
    cutoff <- as.Date(rules$vanaf_datum[result])
    dates <- as.Date(df$Datum)
    result[!is.na(result) & !is.na(cutoff) & (is.na(dates) | dates < cutoff)] <- NA_integer_
  }
  result[!nzchar(key)] <- NA_integer_
  result
}

finance_apply_corrections <- function(df) {
  if (!nrow(df)) return(df)
  cat <- as.character(df$Category)
  rules <- finance_read_rules()
  rule_ix <- finance_rule_matches(df, rules)
  use_rule <- !is.na(rule_ix)
  if (any(use_rule)) cat[use_rule] <- rules$categorie[rule_ix[use_rule]]
  ids <- finance_transaction_ids(df)
  fixes <- finance_read_corrections()
  if (nrow(fixes)) {
    fix_ix <- match(ids, fixes$transactie_id)
    use_fix <- !is.na(fix_ix)
    cat[use_fix] <- fixes$categorie[fix_ix[use_fix]]
  }
  df$Category <- factor(cat, levels = unique(c(levels(df$Category), cat)))
  df
}

