# Gestandaardiseerde DT-tabel (datum+valuta formatting)
# Read-only, compact transaction table shared by ABN and ING.
# DataTables targets are zero-based. Long descriptions wrap without swallowing other columns.
finance_tx_table <- function(df) {
  if (is.null(df)) df <- data.frame()
  wrap_cols <- which(grepl("naam|omschrijving|mededeling|tegenpartij", names(df), ignore.case = TRUE)) - 1L
  defs <- if (length(wrap_cols)) list(list(targets = as.integer(wrap_cols), className = "finance-wrap-text", width = "240px")) else list()
  dt <- DT::datatable(df, rownames = FALSE, filter = "top", class = "stripe hover compact finance-table",
    options = list(pageLength = 10, lengthChange = FALSE, scrollX = TRUE,
                   autoWidth = FALSE, columnDefs = defs, searching = TRUE,
                   ordering = TRUE, dom = "ftip",
                   language = list(search = "Zoeken:", info = "_START_–_END_ van _TOTAL_ regels",
                     infoEmpty = "Geen regels", infoFiltered = "(gefilterd uit _MAX_)",
                     zeroRecords = "Geen overeenkomende transacties",
                     paginate = list(previous = "Vorige", `next` = "Volgende"))))
  if ("Datum" %in% names(df)) dt <- DT::formatDate(dt, "Datum", method = "toLocaleDateString")
  money <- grep("Bedrag|Saldo", names(df), value = TRUE)
  if (length(money)) dt <- DT::formatCurrency(dt, money, currency = "€ ", mark = ".", dec = ",", digits = 2)
  dt
}
