# Shared styling only. Preserve Plotly data, axes and annotations;
# smooth only genuine line series (not bars or secondary-axis spaarquote bars).
finance_modern_plot <- function(p, date_axis = FALSE) {
  p <- plotly::plotly_build(p)
  for (i in seq_along(p$x$data)) {
    tr <- p$x$data[[i]]
    if (identical(tr$type, "scatter") &&
        grepl("lines", tr$mode %||% "lines", fixed = TRUE)) {
      tr$line <- modifyList(if (is.list(tr$line)) tr$line else list(),
                            list(width = 1.6, shape = "spline", smoothing = 0.7))
      if (grepl("markers", tr$mode %||% "", fixed = TRUE)) {
        tr$marker <- modifyList(if (is.list(tr$marker)) tr$marker else list(), list(size = 5.5, opacity = .85))
      }
    }
    p$x$data[[i]] <- tr
  }
  # Tracekleuren worden bewust NIET overschreven.
  # utils_plots.R gebruikt color_map / config.yml voor rekeninghouders.
  # Zo behoudt Plotly de oorspronkelijke kleuren, ook na plotly_build().
  # Event verticals live on x / paper. Keep reference/average lines intact.
  if (length(p$x$layout$shapes)) for (i in seq_along(p$x$layout$shapes)) {
    sh <- p$x$layout$shapes[[i]]
    if (identical(sh$xref, "x") && identical(sh$yref, "paper")) {
      sh$line <- modifyList(if (is.list(sh$line)) sh$line else list(),
                            list(color = "rgba(148,163,184,0.38)", width = 1, dash = "dot"))
      p$x$layout$shapes[[i]] <- sh
    }
  }
  if (length(p$x$layout$annotations)) for (i in seq_along(p$x$layout$annotations)) {
    an <- p$x$layout$annotations[[i]]
    if (identical(an$xref, "x") && identical(an$yref, "paper")) {
      an$hovertext <- an$text
      an$hoverlabel <- list(bgcolor = "#FFFFFF", font = list(size = 11, color = "#35564A"))
      an$font <- list(color = "#9AAC9E", size = 9)
      an$opacity <- .65
      an$bgcolor <- "rgba(255,255,255,0)"
      an$bordercolor <- "rgba(255,255,255,0)"
      an$borderwidth <- 0
      an$y <- 1.015
      an$showarrow <- FALSE
      p$x$layout$annotations[[i]] <- an
    }
  }
  p$x$layout$title <- list(text = "")
  p$x$layout$paper_bgcolor <- "rgba(0,0,0,0)"
  p$x$layout$plot_bgcolor <- "rgba(0,0,0,0)"
  p$x$layout$font <- list(family = "Inter, system-ui, sans-serif", size = 11, color = "#71887C")
  p$x$layout$hoverlabel <- list(bgcolor = "#FFFFFF", bordercolor = "#E1EBE2",
                                 font = list(color = "#203C39", size = 12))
  p$x$layout$xaxis <- modifyList(if (is.list(p$x$layout$xaxis)) p$x$layout$xaxis else list(),
                                  list(showgrid = FALSE, showline = TRUE,
                                       linecolor = "#E1EBE2", ticks = "",
                                       tickfont = list(size = 10, color = "#82968B")))
  p$x$layout$yaxis <- modifyList(if (is.list(p$x$layout$yaxis)) p$x$layout$yaxis else list(),
                                  list(showgrid = TRUE, gridcolor = "#EDF2EC",
                                       gridwidth = .7, zerolinecolor = "#D7E2D9",
                                       tickfont = list(size = 10, color = "#82968B"), ticks = ""))
  if (date_axis) {
    p$x$layout$margin <- modifyList(if (is.list(p$x$layout$margin)) p$x$layout$margin else list(),
                                      list(l = 68, r = 120, t = 28, b = 58))
    p$x$layout$hovermode <- "x unified"
    p$x$layout$xaxis <- modifyList(p$x$layout$xaxis, list(
      tickangle = 0, tickformat = "%b %Y", dtick = "M3",
      rangeslider = list(visible = FALSE),
      rangeselector = list(buttons = list(
        list(count = 6, label = "6 mnd", step = "month", stepmode = "backward"),
        list(count = 1, label = "1 jaar", step = "year", stepmode = "backward"),
        list(step = "all", label = "Alles")),
        bgcolor = "#F5F8F4", activecolor = "#E3F1E9",
        bordercolor = "#E1EBE2", borderwidth = 1,
        font = list(size = 10, color = "#60796D"), x = 0, y = 1.16)))
    p$x$layout$legend <- list(orientation = "h", x = 0, y = -0.24,
                              xanchor = "left", yanchor = "top",
                              font = list(size = 11, color = "#60796D"))
  }
  plotly::config(p, displaylogo = FALSE, responsive = TRUE,
                 modeBarButtonsToRemove = c("lasso2d", "select2d", "autoScale2d"))
}

