current_range_from_input <- function(input, date_min, date_max){
  # Maanden-modus
  if (identical(input$filter_mode, "months")) {
    rng <- as.Date(input$month_range)
    if (!is.null(rng) && length(rng) >= 1 && !is.na(rng[1])) {
      start_m <- lubridate::floor_date(rng[1], "month")
      end_m <- if (length(rng) >= 2 && !is.na(rng[2])) {
        lubridate::ceiling_date(rng[2], "month") - lubridate::days(1)
      } else {
        lubridate::ceiling_date(start_m, "month") - lubridate::days(1)
      }
      return(c(start_m, end_m))
    }
  }
  # Dagen-modus
  if (!is.null(input$date_range) && length(input$date_range) == 2 && all(!is.na(input$date_range))) {
    return(as.Date(input$date_range))
  }
  # Fallback
  c(date_min, date_max)
}

filter_by_range_impl <- function(df, range){
  if (is.null(range) || length(range) != 2 || any(is.na(range))) return(df)
  dplyr::filter(df, Datum >= range[1], Datum <= range[2])
}

# Preset-knoppen "Laatste 30/90/365 dagen"
# - end = min(date_max, Sys.Date())
# - start = max(date_min, end - n + 1)
setup_date_presets <- function(input, session, bounds_reactive) {

  set_range_days <- function(n){
    bounds <- bounds_reactive()
    if (anyNA(bounds)) return(invisible(NULL))
    end   <- min(as.Date(bounds[2]), Sys.Date())
    start <- max(as.Date(bounds[1]), end - n + 1)
    updateRadioButtons(session, "filter_mode", selected = "dates")
    updateDateRangeInput(session, "date_range", start = start, end = end)
  }

  shiny::observeEvent(input$preset_30,  ignoreInit = TRUE, { set_range_days(30)  })
  shiny::observeEvent(input$preset_90,  ignoreInit = TRUE, { set_range_days(90)  })
  shiny::observeEvent(input$preset_365, ignoreInit = TRUE, { set_range_days(365) })
}

