# Gedeelde KPI-helpers voor ING en Kapitaalopbouw.
# De bron is een reactive() met alle transacties; periodekeuzes gelden voor de grafieken.
finance_kpi_period_range <- function(dates, period = "12") {
  dates <- as.Date(dates)
  dates <- dates[!is.na(dates)]
  if (!length(dates)) return(NULL)
  first <- as.Date(lubridate::floor_date(min(dates), "month"))
  last <- as.Date(lubridate::floor_date(max(dates), "month"))
  if (identical(as.character(period), "1")) {
    current_month <- as.Date(lubridate::floor_date(Sys.Date(), "month"))
    if (last >= current_month) {
      last <- seq.Date(from = current_month, by = "-1 month", length.out = 2L)[2L]
    }
    if (last < first) return(NULL)
  }
  n <- suppressWarnings(as.integer(period))
  if (!is.na(n) && n > 0L) {
    # seq.Date voorkomt de niet-bestaande lubridate::months()-aanroep.
    first <- max(first, seq.Date(from = last, by = "-1 month", length.out = n)[n])
  }
  list(start = first,
       end = as.Date(lubridate::ceiling_date(last, "month") - lubridate::days(1)),
       last_month = last)
}

finance_kpi_money <- function(value, signed = FALSE) {
  if (length(value) != 1L || !is.finite(value) || is.na(value)) return("—")
  prefix <- if (value < 0) "− " else if (signed && value > 0) "+ " else ""
  paste0(prefix, "€ ", format(abs(round(value, 2)), big.mark = ".",
                         decimal.mark = ",", nsmall = 2, trim = TRUE))
}

