# Verschil in euro's tussen twee opeenvolgende volledige maanden.
finance_kpi_month_comparison <- function(current, previous) {
  if (length(current) != 1L || length(previous) != 1L ||
      !is.finite(current) || !is.finite(previous)) {
    return("Vorige maand: onvoldoende gegevens")
  }
  paste0("T.o.v. vorige maand: ", finance_kpi_money(current - previous, signed = TRUE))
}

# Voor saldi zijn minimaal drie opeenvolgende maand-eindstanden nodig
# voor de actuele mutatie en de vergelijking met de maand ervoor.
finance_kpi_saldo_month_comparison <- function(monthly, rng) {
  result <- list(current = NA_real_, previous = NA_real_)
  if (is.null(rng) || !nrow(monthly)) return(result)
  dates <- seq.Date(from = rng$last_month, by = "-1 month", length.out = 3L)
  idx <- match(dates, as.Date(monthly$Maand))
  saldo <- rep(NA_real_, 3L)
  ok <- !is.na(idx)
  saldo[ok] <- as.numeric(monthly$Saldo[idx[ok]])
  if (all(is.finite(saldo[1:2]))) result$current <- saldo[1] - saldo[2]
  if (all(is.finite(saldo[2:3]))) result$previous <- saldo[2] - saldo[3]
  result
}

