# ING-normalisatie: identiek formaat voor alle bestaande modules.
finance_normalize_ing <- function(df) {
  names(df) <- stringr::str_squish(names(df))
  missing <- setdiff(finance_tx_ing_cols, names(df))
  if (length(missing)) stop("Ontbrekende ING-kolommen: ", paste(missing, collapse=", "))
  df %>% dplyr::mutate(
    Datum = suppressWarnings(as.Date(as.character(.data$Datum), format="%Y%m%d")),
