# Zelfde ABN-conversie als de oude Excel-loader, maar vanuit SQLite-rijen.
finance_normalize_abn <- function(df_raw) {
  names(df_raw) <- stringr::str_squish(names(df_raw))
  df_raw <- janitor::clean_names(df_raw)
  required_abn <- c('rekeningnummer','muntsoort','transactiedatum','rentedatum',
                    'beginsaldo','eindsaldo','transactiebedrag','omschrijving','wie')
  miss <- setdiff(required_abn, names(df_raw))
  if (length(miss)) stop('Ontbrekende ABN-kolommen: ', paste(miss, collapse=', '))
  df_raw %>% dplyr::mutate(
    Datum = as.Date(as.character(transactiedatum), format='%Y%m%d'),
    `Bedrag (EUR)` = abs(as.numeric(transactiebedrag)),
    `Af Bij` = dplyr::if_else(as.numeric(transactiebedrag) < 0, 'Af', 'Bij'),
    `Saldo na mutatie` = as.numeric(eindsaldo),
    Bedrag_signed = dplyr::if_else(`Af Bij` == 'Af', -`Bedrag (EUR)`, `Bedrag (EUR)`),
    Maand = lubridate::floor_date(Datum, 'month')
  ) %>% dplyr::transmute(
    Datum, `Naam / Omschrijving` = as.character(omschrijving),
    Rekening = as.character(rekeningnummer), Tegenrekening = NA_character_,
    Code = NA_character_, `Af Bij`, `Bedrag (EUR)`,
    Mutatiesoort = NA_character_, Mededelingen = NA_character_,
    `Saldo na mutatie`, Tag=as.character(wie), Bedrag_signed, Maand
  )
}
load_abn_df <- function() {
  finance_normalize_abn(finance_tx_read_raw('ABN'))
}

# Bigbank: getalhelpers
parse_mixed_number <- function(x) {
  if (is.numeric(x)) return(x)
  vapply(as.character(x), parse_mixed_number_scalar, numeric(1), USE.NAMES = FALSE)
}

parse_mixed_number_scalar <- function(x) {
  if (is.na(x)) return(NA_real_)
  x <- trimws(x)
  has_dot  <- grepl("\\.", x)
  has_com  <- grepl(",", x)
  dot_dec  <- grepl("\\.\\d{1,2}$", x)
  com_dec  <- grepl(",\\d{1,2}$", x)
  if (has_dot && has_com) {
    if (com_dec) { x <- gsub("\\.", "", x); x <- sub(",", ".", x)
    } else if (dot_dec) { x <- gsub(",", "", x)
    } else { x <- gsub("[\\.,]", "", x) }
  } else if (has_com && !has_dot) {
    if (com_dec) x <- sub(",", ".", x) else x <- gsub(",", "", x)
  } else if (has_dot && !has_com) {
    if (!dot_dec) x <- gsub("\\.", "", x)
  }
  suppressWarnings(as.numeric(x))
}

format_euro <- function(x, digits = 2) {
  paste0("€ ", format(round(x %||% 0, digits), big.mark = ".", decimal.mark = ",", nsmall = digits))
}

# Bigbank: ingelezen brongegevens komen uitsluitend uit DE/data/data.sqlite.
# Behoud dezelfde kolommen en conversies als de oude Excel-loader.
finance_parse_deposito_date <- function(x) {
  if (inherits(x, "Date")) return(x)
  if (inherits(x, "POSIXt")) return(as.Date(x))

  tekst <- trimws(as.character(x))
  tekst[is.na(x) | !nzchar(tekst)] <- NA_character_
  uit <- as.Date(rep(NA_character_, length(tekst)))

  iso <- !is.na(tekst) & grepl("^[0-9]{4}-[0-9]{2}-[0-9]{2}$", tekst)
  uit[iso] <- as.Date(tekst[iso], format = "%Y-%m-%d")

  # readxl schrijft tijdstempels bij de migratie als ISO-tekst weg.
  timestamp <- !is.na(tekst) & grepl("^[0-9]{4}-[0-9]{2}-[0-9]{2}[ T]", tekst)
  uit[timestamp] <- as.Date(substr(tekst[timestamp], 1L, 10L), format = "%Y-%m-%d")

  compact <- !is.na(tekst) & grepl("^[0-9]{8}$", tekst)
  uit[compact] <- as.Date(tekst[compact], format = "%Y%m%d")

  # Datumcellen die in Excel als serienummer zijn opgeslagen.
  excel <- !is.na(tekst) & grepl("^[0-9]{5}(\\.[0-9]+)?$", tekst) & !compact
  uit[excel] <- as.Date(as.numeric(tekst[excel]), origin = "1899-12-30")

  onbekend <- !is.na(tekst) & is.na(uit)
  if (any(onbekend)) {
    stop("Onbekende depositodatum in SQLite: ", paste(unique(tekst[onbekend]), collapse = ", "))
  }
  uit
}

load_bigbank_df <- function() {
  df_raw <- finance_de_deposito()
  names(df_raw) <- stringr::str_squish(names(df_raw))
  df_raw <- janitor::clean_names(df_raw)

  required <- c(
    "deposito_nr", "eigenaar", "rentepercentage", "looptijd", "looptijddeel",
    "depositobedrag", "activeringsdatum", "vervaldatum",
    "totaal_opgebouwde_rente", "status"
  )
  miss <- setdiff(required, names(df_raw))
  if (length(miss)) {
    stop(sprintf(
      "Ontbrekende kolommen in SQLite-tabel deposito_bron: %s\nGevonden kolommen: %s",
      paste(miss, collapse = ", "), paste(names(df_raw), collapse = ", ")
    ))
  }

  df_raw %>%
    dplyr::mutate(
      deposito_nr             = as.character(.data$deposito_nr),
      eigenaar                = as.character(.data$eigenaar),
      rentepercentage         = as.numeric(.data$rentepercentage),
      looptijd                = suppressWarnings(as.integer(.data$looptijd)),
      looptijddeel            = as.character(.data$looptijddeel),
      depositobedrag          = parse_mixed_number(.data$depositobedrag),
      totaal_opgebouwde_rente = parse_mixed_number(.data$totaal_opgebouwde_rente),
      activeringsdatum        = finance_parse_deposito_date(.data$activeringsdatum),
      vervaldatum             = finance_parse_deposito_date(.data$vervaldatum),
      status                  = stringr::str_to_title(as.character(.data$status))
    ) %>%
    dplyr::rename(totaalopgebouwde_rente = totaal_opgebouwde_rente) %>%
    dplyr::select(
      deposito_nr, eigenaar, rentepercentage, looptijd, looptijddeel,
      depositobedrag, activeringsdatum, vervaldatum,
      totaalopgebouwde_rente, status
    )
}

