/* Close the expanded Shiny/Bootstrap navigation after selecting a tab. */
(function () {
  "use strict";
  document.addEventListener("click", function (event) {
    var target = event.target;
    if (!target || !target.closest) return;
    var link = target.closest('a[data-value], button[data-value], [role="tab"]');
    if (!link) return;
    var menu = link.closest('.navbar-collapse');
    if (!menu) return;
    var nav = menu.closest('.navbar');
    if (!nav) return;
    var toggle = nav.querySelector('.navbar-toggler, .navbar-toggle');
    if (!toggle || !toggle.getClientRects().length || getComputedStyle(toggle).visibility === 'hidden') return;
    // Capture the click even if Shiny or Bootstrap stops bubbling; let tab selection finish first.
    setTimeout(function () {
      if (!menu.isConnected || !(menu.classList.contains('show') || menu.classList.contains('in') || toggle.getAttribute('aria-expanded') === 'true')) return;
      if (window.bootstrap && window.bootstrap.Collapse) {
        var Collapse = window.bootstrap.Collapse;
        var instance = Collapse.getInstance(menu) || new Collapse(menu, {toggle:false});
        instance.hide();
      } else if (window.jQuery && typeof window.jQuery.fn.collapse === 'function') {
        window.jQuery(menu).collapse('hide');
      } else {
        toggle.click();
      }
    }, 0);
  }, true);
})();


/* Grobben mobile charts: keep the original Shiny widget and its events. */
(() => {
  'use strict';
  if (window.grobbenMobileCharts) return;
  window.grobbenMobileCharts = true;
  let active = null, scheduled = false, resizeTimer;
  const selector = '.plotly.html-widget-output, .plotly.shiny-bound-output';
  const ready = g => window.Plotly && g && g._fullLayout && Array.isArray(g.data);
  const button = (label, title, fn) => {
    const b = document.createElement('button');
    b.type = 'button'; b.textContent = label; b.title = title;
    b.setAttribute('aria-label', title); b.addEventListener('click', fn);
    return b;
  };
  function resize(g) {
    if (!ready(g)) return;
    requestAnimationFrame(() => requestAnimationFrame(() => {
      if (ready(g) && g.getBoundingClientRect().width > 0)
        Promise.resolve(window.Plotly.Plots.resize(g)).catch(console.warn);
    }));
  }
  function axes(g) {
    return Object.keys(g._fullLayout).filter(k => /^(x|y)axis\d*$/.test(k) && Array.isArray(g._fullLayout[k].range));
  }
  function relayout(g, changes) {
    if (ready(g)) Promise.resolve(window.Plotly.relayout(g, changes)).catch(console.warn);
  }
  function zoom(g, factor) {
    if (!ready(g)) return;
    const changes = {};
    axes(g).forEach(k => {
      const a = g._fullLayout[k];
      if (a.fixedrange) return;
      const date = a.type === 'date';
      const nums = a.range.map(v => date ? Date.parse(String(v).replace(' ', 'T') + (/Z$|[+-]\d\d:\d\d$/.test(String(v)) ? '' : 'Z')) : Number(v));
      if (!nums.every(Number.isFinite)) return;
      const mid = (nums[0] + nums[1]) / 2;
      changes[k + '.range'] = nums.map(v => {
        const n = mid + (v-mid)*factor;
        return date ? new Date(n).toISOString() : n;
      });
      changes[k + '.autorange'] = false;
    });
    if (Object.keys(changes).length) relayout(g, changes);
  }
  function close() {
    if (!active) return;
    const a = active; active = null;
    a.panel.classList.remove('gmc-full');
    document.body.classList.remove('gmc-lock');
    a.open.hidden = false; a.tools.hidden = true;
    a.open.setAttribute('aria-expanded','false');
    if (a.open.isConnected) a.open.focus({preventScroll:true});
    resize(a.g);
  }
  function open(a) {
    if (!ready(a.g)) return;
    if (active) close();
    active = a;
    a.initial = {};
    axes(a.g).forEach(k => {
      const axis = a.g._fullLayout[k];
      a.initial[k+'.autorange'] = axis.autorange;
      if (!axis.autorange) a.initial[k+'.range'] = axis.range.slice();
    });
    a.initial.dragmode = a.g._fullLayout.dragmode;
