    resize(a.g);
  }
  function periodControls() {
    document.querySelectorAll('select[id$="-period"], select[id$="-kpi_period"]').forEach(s => {
      if (s.multiple || s.selectize || s.dataset.gmcPeriod) return;
      s.dataset.gmcPeriod = '1';
