      const value = document.createElement('span'); value.className = 'gmc-period-value';
      value.setAttribute('aria-live', 'polite');
      const prev = button('‹', 'Kortere periode', () => step(-1));
      const next = button('›', 'Langere periode', () => step(1));
      function sync() {
        const i = s.selectedIndex;
        value.textContent = i < 0 ? '—' : s.options[i].text;
        prev.disabled = s.disabled || i <= 0;
        next.disabled = s.disabled || i < 0 || i >= s.options.length-1;
      }
      function step(n) {
        const i = s.selectedIndex + n;
        if (i < 0 || i >= s.options.length) return;
        s.selectedIndex = i;
        s.dispatchEvent(new Event('change', {bubbles:true}));
        sync();
      }
      bar.append(prev, value, next); s.after(bar);
      s.classList.add('gmc-period-native'); s.addEventListener('change', sync);
      if (window.jQuery) window.jQuery(s).on('change.gmcPeriod', sync);
      new MutationObserver(sync).observe(s, {childList:true,subtree:true,attributes:true,attributeFilter:['disabled']});
      sync();
    });
  }
  function scan() {
    scheduled = false;
    periodControls();
    document.querySelectorAll(selector).forEach(g => {
      if (g.dataset.gmc) return;
      const panel = g.closest('.gmc-chart');
      if (!panel || panel.querySelectorAll(selector).length !== 1) return;
      const toolbar = document.createElement('div'); toolbar.className = 'gmc-bar';
      const tools = document.createElement('div'); tools.className = 'gmc-tools'; tools.hidden = true;
      const a = {g, panel, tools};
      if (g.id.includes('heat_')) panel.classList.add('gmc-heat');
      a.open = button('⛶ Vergroten', 'Grafiek schermvullend openen', () => open(a));
      a.open.setAttribute('aria-expanded','false');
      a.exit = button('✕ Sluiten', 'Schermvullende grafiek sluiten', close);
      tools.append(button('＋', 'Inzoomen', () => zoom(g,.7)), button('−', 'Uitzoomen', () => zoom(g,1/.7)),
        button('Schuiven', 'Verschuifmodus', () => relayout(g,{dragmode:'pan'})),
        button('Zoom', 'Selecteer een zoomgebied', () => relayout(g,{dragmode:'zoom'})),
        button('↺', 'Oorspronkelijke assen herstellen', () => relayout(g,a.initial || {})), a.exit);
      toolbar.append(a.open,tools); g.before(toolbar); g.dataset.gmc = '1';
    });
