/* Non-blocking startup overlay: first KPI, error, manual dismissal or timeout. */
(function () {
  "use strict";
  var finished = false, timer, observer;
  var ids = ["dashboard-kpi_netto", "dashboard-kpi_spaarquote"];
  function done() {
    if (finished) return;
    finished = true;
    clearTimeout(timer);
    if (observer) observer.disconnect();
    var overlay = document.getElementById("finance-startup-overlay");
    if (!overlay) return;
    overlay.classList.add("is-finished");
    overlay.setAttribute("aria-hidden", "true");
    setTimeout(function () { overlay.remove(); }, 350);
  }
  function check() {
    if (ids.some(function (id) {
      var el = document.getElementById(id);
      return el && (el.querySelector(".dashboard-kpi") || el.classList.contains("shiny-output-error"));
    })) done();
  }
  function start() {
    if (finished) return;
    var dismiss = document.getElementById("finance-startup-dismiss");
    if (dismiss) dismiss.addEventListener("click", done);
    if (window.jQuery) {
      window.jQuery(document).on("shiny:value.financeStartup shiny:error.financeStartup", function (e) {
        if (ids.indexOf(e.name) !== -1) done();
      });
    }
    observer = new MutationObserver(check);
    observer.observe(document.body, {childList:true, subtree:true, attributes:true, attributeFilter:["class"]});
    timer = setTimeout(done, 12000);
    check();
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", start, {once:true});
  else start();
})();

