.finance-db-page { max-width: 1450px; margin: 0 auto; color: #203C39; }
.finance-db-intro { margin: 4px 0 23px; }
.finance-db-eyebrow { font-size: 11px; color: #087C68; font-weight: 750; letter-spacing: .11em; margin-bottom: 9px; }
.finance-db-intro h2 { font-size: clamp(23px,2.2vw,29px); font-weight: 750; margin: 0 0 7px; }
.finance-db-intro p { font-size: 13px; color: #71867A; margin: 0; line-height: 1.55; }
.finance-db-panel { background: #fff; border: 1px solid #DFE9E1; border-radius: 16px; padding: 23px 24px; box-shadow: 0 2px 12px rgba(26,57,46,.035); min-width: 0; }
.finance-db-toolbar { display: flex; flex-wrap: wrap; align-items: end; gap: 12px; margin-bottom: 19px; }
.finance-db-table-picker { min-width: min(100%,330px); flex: 1; max-width: 450px; }
.finance-db-toolbar .shiny-input-container { margin-bottom: 0; }
.finance-db-toolbar label { font-size: 12px; font-weight: 650; color: #587369; margin-bottom: 6px; }
.finance-db-toolbar .btn { margin-bottom: 0; padding: 9px 13px; }
.finance-db-stat-row { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: 12px; margin-bottom: 18px; }
.finance-db-stat { display: flex; flex-direction: column; gap: 5px; padding: 15px 17px; background: #F6F9F6; border: 1px solid #E5EEE6; border-radius: 11px; min-width: 0; }
.finance-db-stat span { color: #72877F; font-size: 11px; }
.finance-db-stat strong { color: #203C39; font-size: 20px; font-weight: 750; overflow-wrap: anywhere; }
.finance-db-table-help { font-size: 12px; color: #72877F; margin-bottom: 12px; }
.finance-db-table-wrap { width: 100%; min-width: 0; overflow: hidden; }
.finance-db-table-wrap .dataTables_wrapper { font-size: 12px; color: #52685D; }
.finance-db-table-wrap table.dataTable { width: 100% !important; border: 1px solid #E2EBE4; }
.finance-db-table-wrap table.dataTable thead th { background: #F5F8F5; color: #60776A; font-size: 11px; border-bottom-color: #E1EAE2 !important; white-space: nowrap; }
.finance-db-table-wrap table.dataTable tbody tr:hover td { background: #F3F8F4 !important; }
.finance-db-table-wrap table.dataTable tbody td { font-size: 12px; line-height: 1.45; max-width: 360px; overflow-wrap: anywhere; }
.finance-db-table-wrap .dataTables_filter input, .finance-db-table-wrap .dataTables_length select,
.finance-db-table-wrap table.dataTable thead input { border: 1px solid #DCE7DF; border-radius: 7px; background: #fff; color: #203C39; }
