.finance-db-field label { color: #526F61; font-size: 12px; font-weight: 650; }
.finance-db-field .checkbox label { font-size: 11px; font-weight: 500; color: #778A80; }
.finance-db-delete-key { background: #F6F9F6; border: 1px solid #E4ECE5; border-radius: 9px; padding: 11px 13px; margin: 10px 0 15px; color: #304F41; font-size: 12px; overflow-wrap: anywhere; }
@media (max-width: 767.98px) { .finance-db-editor-fields { grid-template-columns: 1fr; } }

/* Dashboard: transactiesignalen */
.dashboard-signal-panel .form-group { margin: 10px 0 14px; }
.dashboard-signal-actions { display: flex; flex-wrap: wrap; gap: 8px; margin: 14px 0 6px; }
.dashboard-signal-detail { background: var(--bs-tertiary-bg, #f5f7f8); border-radius: 10px; padding: 13px 16px; margin-top: 12px; }
.dashboard-signal-detail p { margin: 6px 0 4px; }
.dashboard-signal-panel table.dataTable tbody tr { cursor: pointer; }

/* Vaste lasten & abonnementen — zelfstandige analysepagina */
.tab-pane[data-value="vaste_lasten"] .vl-intro { margin-bottom: 20px; }
.tab-pane[data-value="vaste_lasten"] .vl-muted { color: #758A80; font-size: .88rem; }
.tab-pane[data-value="vaste_lasten"] .vl-kpi-grid {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px; margin-bottom: 20px;
}
.tab-pane[data-value="vaste_lasten"] .vl-kpi,
.tab-pane[data-value="vaste_lasten"] .vl-block {
  background: #fff; border: 1px solid #E1EBE3; border-radius: 14px;
  padding: 20px; margin-bottom: 15px;
}
.tab-pane[data-value="vaste_lasten"] .vl-kpi span { display: block; font-size: .8rem; color: #758A80; }
.tab-pane[data-value="vaste_lasten"] .vl-kpi strong { display: block; font-size: 1.65rem; color: #203C39; }
.tab-pane[data-value="vaste_lasten"] .vl-block h4 { font-size: 1rem; font-weight: 700; margin-bottom: 15px; }
@media (max-width: 1150px) {
  .tab-pane[data-value="vaste_lasten"] .vl-kpi-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 575px) {
  .tab-pane[data-value="vaste_lasten"] .vl-kpi-grid { grid-template-columns: 1fr; }
}
